  var CARDS = {"20-017": {"lede": "Покажет, сколько в крови эритроцитов, лейкоцитов, тромбоцитов и гемоглобина.", "blocks": [{"h": "Что это", "p": ["В крови есть эритроциты, лейкоциты и тромбоциты. Эритроциты переносят кислород ко всем органам — для этого в них есть гемоглобин. Лейкоциты защищают от инфекций; их несколько видов, и у каждого своя работа. Тромбоциты — не целые клетки, а их маленькие частицы: они помогают остановить кровотечение.", "Анализ показывает, сколько в крови эритроцитов, лейкоцитов, тромбоцитов и гемоглобина и как лейкоциты делятся по видам."]}, {"h": "Какие бывают признаки", "p": ["Изменения в крови часто ничем не ощущаются — их находят при диспансеризации или плановой проверке. Иногда бывает:"], "list": ["усталость, бледность, одышка, головокружение — когда мало гемоглобина", "частые простуды, температура без понятной причины — при изменениях лейкоцитов", "синяки без причины, кровоточивость дёсен — когда мало тромбоцитов"]}, {"h": "Когда назначают", "list": ["при диспансеризации, профосмотре и перед операцией", "при усталости, бледности, одышке, синяках без причины", "при температуре и других признаках инфекции", "при беременности — по плану врача", "для контроля лечения"]}, {"h": "Как подготовиться", "list": ["Особой подготовки обычно не нужно. Если в тот же день сдаёте биохимию, приходите натощак.", "Лекарства сами не отменяйте — скажите о них медсестре."]}, {"h": "Как понять результат", "p": ["Врач смотрит на все показатели вместе. Сниженный гемоглобин может говорить об анемии, например из-за нехватки железа. Лейкоциты повышаются при инфекции или воспалении, снижаются — например, после вирусной инфекции. Небольшие отклонения часто не требуют лечения. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем считать разные виды лейкоцитов?", "a": "Их соотношение помогает понять, с чем связано изменение лейкоцитов."}, {"q": "Почему нормы в лабораториях разные?", "a": "Из-за разных приборов и методов. Сравнивайте результат с нормой своего бланка."}]}, "40-111": {"lede": "Покажет, хватает ли организму запасов железа.", "blocks": [{"h": "Что это", "p": ["Ферритин — белок, в котором организм хранит железо про запас.", "Железо нужно, чтобы эритроциты переносили кислород ко всем органам. Если запасов не хватает, со временем снижается гемоглобин и органы получают меньше кислорода.", "Анализ показывает, хватает ли запасов железа."]}, {"h": "Какие бывают признаки", "p": ["Если железа не хватает, бывает:"], "list": ["усталость и слабость", "бледность кожи", "одышка и сердцебиение при обычной нагрузке", "головокружение", "ломкие ногти, выпадение волос"], "note": "Запасы железа иногда уменьшаются раньше, чем появляются жалобы."}, {"h": "Когда назначают", "list": ["при усталости, одышке, головокружении, бледности", "если гемоглобин в общем анализе крови снижен", "при обильных менструациях и во время беременности", "при болезнях кишечника, когда пища плохо усваивается", "чтобы проверить, помогает ли лечение препаратами железа"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, воду пить можно.", "Если недавно болели с температурой, скажите врачу: воспаление влияет на результат.", "Лекарства и добавки сами не отменяйте."]}, {"h": "Как понять результат", "p": ["Низкий ферритин обычно значит, что запасы железа уменьшились. Высокий бывает при избытке железа, а также при воспалении, инфекции, болезнях печени. При воспалении ферритин может быть высоким, даже если железа мало, поэтому врач иногда добавляет С-реактивный белок. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Гемоглобин в норме — зачем ферритин?", "a": "Запасы железа могут уменьшиться раньше, чем снизится гемоглобин."}, {"q": "Чем ферритин отличается от анализа на железо?", "a": "Железо в крови меняется от еды и лекарств, а ферритин показывает запасы."}]}, "30-010": {"lede": "Покажет, не работает ли щитовидная железа слишком слабо или слишком активно.", "blocks": [{"h": "Что это", "p": ["Щитовидная железа вырабатывает гормоны, которые управляют обменом веществ: от них зависят энергия, вес, сердцебиение, температура тела.", "ТТГ вырабатывает гипофиз — небольшая железа в мозге. Он подсказывает щитовидной железе, сколько гормонов производить. Поэтому по ТТГ видно, не работает ли она слишком слабо или слишком активно."]}, {"h": "Какие бывают признаки", "p": ["Если гормонов щитовидной железы мало или много, бывает:"], "list": ["мало: усталость, сонливость, зябкость, прибавка веса, сухая кожа, запоры", "много: сердцебиение, потливость, раздражительность, похудение без причины, дрожь в руках"]}, {"h": "Когда назначают", "list": ["при усталости, изменении веса, сердцебиении без причины", "при планировании и в начале беременности", "при приёме гормонов щитовидной железы", "при узлах в щитовидной железе"]}, {"h": "Как подготовиться", "list": ["Особой подготовки обычно не нужно.", "Принимаете гормоны щитовидной железы — спросите врача, пить ли таблетку до анализа.", "Скажите врачу, если принимаете биотин (витамин B7) из добавок для волос и ногтей: он может исказить результат."]}, {"h": "Как понять результат", "p": ["Если ТТГ выше нормы, обычно гормонов щитовидной железы мало. Если ниже — гормонов может быть слишком много. Причину анализ не показывает: врач может добавить другие анализы или перепроверить ТТГ через 2–3 месяца. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Нужно ли проверять ТТГ при беременности?", "a": "Клинические рекомендации советуют — при планировании или в начале беременности."}, {"q": "Почему врач назначил только ТТГ?", "a": "Его обычно проверяют первым, остальные гормоны — если он не в норме."}]}, "40-297": {"lede": "Покажет, хватает ли организму витамина D.", "blocks": [{"h": "Что это", "p": ["Витамин D помогает организму усваивать кальций — без него кости становятся менее прочными. Он образуется в коже под солнцем и немного поступает с едой.", "Анализ показывает витамин D в той форме, в которой он запасается в организме, — по ней лучше всего видно, хватает ли его."]}, {"h": "Какие бывают признаки", "p": ["Нехватка витамина D часто ничем не ощущается. При долгой и сильной нехватке бывает:"], "list": ["боль в костях и мышцах", "мышечная слабость", "у взрослых — хрупкие кости, переломы от небольшой травмы", "у детей — нарушение роста костей (рахит)"], "note": "Всем подряд этот анализ не рекомендуют — его назначают, если есть риск нехватки."}, {"h": "Когда назначают", "list": ["при остеопорозе, переломах от небольшой травмы, частых падениях в пожилом возрасте", "при болезнях кишечника, когда пища плохо усваивается", "при болезнях почек или печени", "при приёме лекарств, которые влияют на витамин D", "чтобы проверить, как действует назначенный врачом витамин D"]}, {"h": "Как подготовиться", "list": ["Особой подготовки не нужно.", "Скажите врачу, какие витамины и добавки принимаете."]}, {"h": "Как понять результат", "p": ["Низкий уровень говорит о нехватке витамина D — она может сказываться на костях и мышцах. Очень высокий обычно связан с избытком добавок, и это тоже вредно. Нужно ли принимать витамин D и в какой дозе, решает врач. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему анализ не советуют сдавать всем?", "a": "Нет доказательств, что проверка всех подряд приносит пользу."}, {"q": "Можно ли сдать анализ, если я уже пью витамин D?", "a": "Да. Скажите об этом врачу — он учтёт это при оценке."}]}, "40-047": {"lede": "Покажет уровень сахара в крови натощак.", "blocks": [{"h": "Что это", "p": ["Глюкоза — сахар в крови, главный источник энергии для клеток. Уровень сахара регулирует гормон инсулин: он помогает глюкозе попасть из крови в клетки.", "Анализ показывает, сколько глюкозы в крови сейчас. Он помогает выявить диабет и предиабет — когда сахар уже выше нормы, но диабета ещё нет."]}, {"h": "Какие бывают признаки", "p": ["Повышенный сахар долго может ничем не проявляться. Иногда бывает:"], "list": ["сильная жажда", "частое мочеиспускание", "похудение без причины", "усталость", "раны и царапины долго заживают"], "note": "Поэтому сахар проверяют и без жалоб — например, при диспансеризации."}, {"h": "Когда назначают", "list": ["при диспансеризации и профосмотре", "при лишнем весе, высоком давлении, диабете у родственников", "при сильной жажде, частом мочеиспускании, похудении без причины", "при беременности — по плану врача"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды должно пройти от 8 до 14 часов. Пить можно только чистую воду.", "Если вы лечите диабет, спросите врача, как быть с утренними лекарствами."]}, {"h": "Как понять результат", "p": ["Глюкоза выше нормы может говорить о предиабете или диабете. Но она бывает повышена и временно — при стрессе, тяжёлой болезни, приёме некоторых лекарств. Поэтому диагноз диабета врач обычно ставит после повторного анализа. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Можно ли утром чай или кофе?", "a": "Нет. Натощак — значит без еды и напитков, кроме чистой воды."}, {"q": "Чем глюкоза отличается от гликированного гемоглобина?", "a": "Глюкоза — сахар в момент анализа, гликированный гемоглобин — средний сахар за 2–3 месяца."}]}, "40-141": {"lede": "Покажет средний уровень сахара в крови за последние 2–3 месяца.", "blocks": [{"h": "Что это", "p": ["Гемоглобин — белок в эритроцитах, который переносит кислород. Часть гемоглобина соединяется с сахаром крови: чем выше сахар, тем больше такого гемоглобина.", "Эритроциты живут около трёх месяцев, поэтому анализ показывает средний сахар за последние 2–3 месяца, а не только в день сдачи."]}, {"h": "Какие бывают признаки", "p": ["Когда сахар долго повышен, бывает:"], "list": ["жажда и частое мочеиспускание", "усталость", "похудение без причины", "раны долго заживают"], "note": "Часто признаков нет совсем — поэтому анализ назначают и без жалоб."}, {"h": "Когда назначают", "list": ["чтобы выявить диабет 2 типа и предиабет", "при жажде, частом мочеиспускании, похудении без причины", "если диабет уже есть — чтобы оценить лечение", "если глюкоза натощак выше нормы — по назначению врача"]}, {"h": "Как подготовиться", "list": ["Натощак не обязательно — можно в любое время дня. Если вместе сдаёте глюкозу или биохимию — приходите натощак.", "Скажите врачу о беременности, недавней кровопотере или переливании крови."]}, {"h": "Как понять результат", "p": ["Чем выше результат, тем выше был сахар в последние месяцы. Анализ бывает неточным при анемии, беременности, болезнях почек и печени, после кровопотери — тогда врач опирается на другие анализы. Диабет беременных по нему не выявляют. Норму указывает лаборатория в бланке, а цель при диабете — врач."]}], "faq": [{"q": "Глюкоза в норме — зачем этот анализ?", "a": "Глюкоза — сахар в момент анализа, а этот анализ — за несколько месяцев."}, {"q": "Как часто сдавать при диабете?", "a": "Обычно раз в 3 месяца, но частоту определяет врач."}]}, "00-014": {"lede": "Покажет уровень холестерина и других жиров крови, от которых зависит здоровье сосудов.", "blocks": [{"h": "Что это", "p": ["Холестерин — жироподобное вещество. Он нужен организму для клеток и гормонов, но его избыток откладывается в стенках сосудов в виде бляшек и сужает их.", "По крови холестерин переносится в разных «упаковках». ЛПНП («плохой») доставляет его к органам, и при избытке он оседает в стенках сосудов. ЛПВП («хороший») уносит лишний холестерин в печень. Анализ показывает общий холестерин, его части и триглицериды — ещё один вид жиров крови."]}, {"h": "Какие бывают признаки", "p": ["Высокий холестерин обычно никак не ощущается — узнать о нём можно только по анализу."], "note": "Поэтому его проверяют и без жалоб: взрослым после 40 лет, при болезнях сердца у родственников, при высоком давлении и диабете."}, {"h": "Когда назначают", "list": ["взрослым старше 40 лет — чтобы оценить риск для сердца и сосудов", "если у родственников был ранний инфаркт или очень высокий холестерин", "при высоком давлении, диабете, лишнем весе, курении", "при приёме лекарств, снижающих холестерин"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, воду пить можно.", "Накануне — без алкоголя и жирной еды."]}, {"h": "Как понять результат", "p": ["Высокие ЛПНП и триглицериды повышают риск атеросклероза — сужения сосудов бляшками. Врач оценивает результат вместе с возрастом, давлением, курением и сахаром: так считают общий риск. Целевые значения у всех разные, их назначает врач. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему у меня и у соседа разные цели?", "a": "Цель зависит от общего риска: возраста, болезней, наследственности."}, {"q": "Можно ли сдать не натощак?", "a": "Иногда врач разрешает. Но если триглицериды раньше были повышены — только натощак."}]}, "40-026": {"lede": "Покажет, нет ли признаков повреждения клеток печени.", "blocks": [{"h": "Что это", "p": ["Печень очищает кровь, участвует в обмене веществ и пищеварении.", "АЛТ — фермент, то есть вещество, которое ускоряет реакции в клетках. Больше всего его в печени. Когда клетки печени повреждаются, АЛТ выходит в кровь — поэтому анализ помогает заметить проблемы с печенью."]}, {"h": "Какие бывают признаки", "p": ["Печень долго может не давать о себе знать. Иногда при её болезнях бывает:"], "list": ["слабость, быстрая утомляемость", "тошнота, плохой аппетит", "тяжесть справа под рёбрами", "желтизна кожи и глаз, тёмная моча"], "note": "АЛТ часто меняется раньше, чем появляются жалобы."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии", "при тошноте, слабости, желтизне кожи, тёмной моче", "при приёме лекарств, которые могут влиять на печень", "при лишнем весе, диабете, частом употреблении алкоголя", "после контакта с больным гепатитом"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, воду пить можно. За сутки — без алкоголя.", "За несколько дней — без непривычно тяжёлых тренировок: после силовой нагрузки АЛТ может быть повышен до недели."]}, {"h": "Как понять результат", "p": ["Повышенный АЛТ может говорить о повреждении клеток печени. Причины разные: ожирение печени, алкоголь, вирусные гепатиты, некоторые лекарства и добавки. АЛТ может временно расти после тренировок и уколов в мышцу. Врач оценивает его вместе с другими анализами. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "АЛТ в норме — с печенью всё в порядке?", "a": "Не всегда: при некоторых болезнях печени он близок к норме."}, {"q": "Пью лекарства от холестерина. Нужен ли АЛТ?", "a": "Некоторые из них повышают АЛТ. Частоту проверки определит врач."}]}, "40-063": {"lede": "Покажет, как почки справляются с очищением крови.", "blocks": [{"h": "Что это", "p": ["Почки очищают кровь от ненужных веществ и выводят их с мочой.", "Креатинин образуется в мышцах при их работе. Здоровые почки его выводят, а если почки работают хуже, креатинина в крови становится больше. По креатинину, возрасту и полу врач рассчитывает СКФ — скорость, с которой почки очищают кровь."]}, {"h": "Какие бывают признаки", "p": ["В начале болезни почек жалоб обычно нет. Позже бывает:"], "list": ["отёки на лице и ногах", "мочи стало заметно больше или меньше", "пенистая моча", "слабость, плохой аппетит"], "note": "Поэтому при диабете и высоком давлении креатинин проверяют и без жалоб."}, {"h": "Когда назначают", "list": ["при плановой проверке здоровья", "при диабете, высоком давлении, болезнях сердца", "при отёках, изменении количества мочи, пенистой моче", "при приёме лекарств, которые могут влиять на почки"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, воду пить можно.", "За 12 часов не ешьте мясо, накануне — без тяжёлых тренировок: это может временно повысить креатинин."]}, {"h": "Как понять результат", "p": ["Креатинин выше нормы может говорить о том, что почки работают хуже. Но он бывает повышен и без болезни почек: при обезвоживании, большой мышечной массе, после мяса, нагрузки или приёма креатина. По одному результату диагноз не ставят. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем СКФ, если есть креатинин?", "a": "Креатинин зависит от мышц, возраста и пола. СКФ это учитывает и точнее показывает работу почек."}, {"q": "Креатинин в норме — почки здоровы?", "a": "Не всегда: в начале болезни почек он бывает в норме. Иногда врач назначает анализ мочи на альбумин."}]}, "10-008": {"lede": "Покажет, нет ли изменений, связанных с почками и мочевыми путями.", "blocks": [{"h": "Что это", "p": ["Почки фильтруют кровь и выводят лишнее с мочой. По составу мочи видно, как работают почки и нет ли воспаления в мочевых путях.", "Анализ показывает цвет и прозрачность мочи, есть ли в ней белок, глюкоза, кровь, клетки, кристаллы и бактерии."]}, {"h": "Какие бывают признаки", "p": ["При проблемах с почками и мочевыми путями бывает:"], "list": ["боль или жжение при мочеиспускании", "частые позывы", "моча мутная или изменила цвет", "боль в пояснице", "отёки"]}, {"h": "Когда назначают", "list": ["при плановой проверке и перед операцией", "при боли или жжении при мочеиспускании, частых позывах", "если моча изменила цвет", "при беременности — по плану врача", "при диабете и болезнях почек — для контроля"]}, {"h": "Как подготовиться", "list": ["Соберите первую утреннюю мочу, перед этим подмойтесь.", "Первую часть мочи спустите в унитаз, среднюю соберите в стерильный контейнер.", "Принесите его как можно скорее, лучше в течение 2 часов.", "Во время менструации анализ лучше перенести — спросите врача."]}, {"h": "Как понять результат", "p": ["Врач смотрит на сочетание показателей. Лейкоциты и бактерии могут говорить о воспалении в мочевых путях. Белок, глюкоза и кровь требуют внимания врача, но кровь иногда появляется временно, например после тяжёлой нагрузки. Свёкла и некоторые лекарства меняют цвет мочи. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Можно собрать мочу вечером и принести утром?", "a": "Нет: при долгом хранении результат искажается."}, {"q": "Где взять контейнер?", "a": "{где взять контейнер}"}]}, "60-011": {"lede": "Покажет общее количество IgE — антител, которые связаны в том числе с аллергией.", "blocks": [{"h": "Что это", "p": ["Иммунитет защищает организм от микробов. При аллергии он ошибочно реагирует на безвредные вещества — пыльцу, пыль, шерсть, продукты.", "IgE — антитела, которые участвуют в такой реакции. Анализ показывает их общее количество. Он не говорит, на что аллергия, и сам по себе её не подтверждает и не исключает."]}, {"h": "Какие бывают признаки", "p": ["Аллергия может проявляться так:"], "list": ["насморк, чихание, заложенность носа", "зуд и слезотечение глаз", "кашель, приступы удушья", "сыпь, зуд кожи, крапивница"], "note": "Похожие признаки бывают при простуде и других болезнях."}, {"h": "Когда назначают", "list": ["при насморке, чихании, зуде глаз, приступах кашля", "при кожном зуде, сыпи, крапивнице, экземе", "когда врач ищет другие причины, например глисты"]}, {"h": "Как подготовиться", "list": ["Особой подготовки обычно не нужно.", "Если принимаете лекарства от аллергии, скажите врачу. Сами их не отменяйте."]}, {"h": "Как понять результат", "p": ["Повышенный IgE бывает при аллергии, а также при глистах, курении и некоторых других болезнях. Нормальный IgE аллергию не исключает. Чтобы найти конкретный аллерген, врач назначает специфические IgE или кожные пробы. Норма зависит от возраста — её указывают в бланке результата."]}], "faq": [{"q": "Чем общий IgE отличается от специфических?", "a": "Общий — всё количество IgE. Специфический — реакция на один аллерген, например пыльцу берёзы."}, {"q": "Можно ли по анализу решить, какие продукты исключить?", "a": "Нет. Сами ничего не исключайте — это решает врач по анализам и симптомам."}]}, "41-016": {"lede": "Покажет уровень белка ПСА, который помогает врачу оценить состояние простаты.", "blocks": [{"h": "Что это", "p": ["Простата (предстательная железа) — небольшой орган у мужчин под мочевым пузырём. Она вырабатывает часть семенной жидкости.", "ПСА — белок, который вырабатывают её клетки. Он повышается при разных болезнях простаты, не только при раке, поэтому это не анализ «на рак». Сдавать ли его, решите с врачом."]}, {"h": "Какие бывают признаки", "p": ["При увеличении или воспалении простаты бывает:"], "list": ["частое мочеиспускание, особенно ночью", "слабая или прерывистая струя", "ощущение, что мочевой пузырь опорожнился не до конца", "боль или жжение при мочеиспускании"], "note": "На ранних стадиях жалоб часто нет."}, {"h": "Когда назначают", "list": ["мужчинам старше 50 лет, при раке простаты у близких родственников — старше 45", "при учащённом или затруднённом мочеиспускании", "после лечения болезней простаты"]}, {"h": "Как подготовиться", "list": ["За 48 часов — без семяизвержения, велосипеда и нагрузок до одышки.", "Скажите врачу о недавней инфекции мочевых путей, осмотре простаты, биопсии или операции и о лекарствах от увеличения простаты: они снижают ПСА."]}, {"h": "Как понять результат", "p": ["ПСА повышается при увеличении простаты, простатите, после осмотра и процедур — и при раке. Один повышенный результат не означает рак: врач может попросить пересдать анализ или назначить обследования. Нормальный ПСА болезнь полностью не исключает. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему перед анализом нельзя ездить на велосипеде?", "a": "Это может временно повысить ПСА, и результат будет менее точным."}, {"q": "Как часто сдавать ПСА?", "a": "Решает врач — по возрасту, наследственности и прошлым результатам."}]}, "20-001": {"lede": "Покажет, сколько в крови эритроцитов, лейкоцитов, тромбоцитов и гемоглобина.", "blocks": [{"h": "Что это", "p": ["В крови есть эритроциты, лейкоциты и тромбоциты. Эритроциты с помощью гемоглобина переносят кислород, лейкоциты защищают от инфекций, а тромбоциты — не клетки, а частицы крупных клеток костного мозга — помогают остановить кровотечение. Анализ показывает, сколько всего этого в крови."]}, {"h": "Какие бывают признаки", "p": ["Если показатели крови изменены, бывает:"], "list": ["усталость, бледность, одышка — когда мало гемоглобина", "частые инфекции, температура без понятной причины", "синяки без причины, кровоточивость дёсен"], "note": "Часто изменения ничем не ощущаются."}, {"h": "Когда назначают", "list": ["при диспансеризации, профосмотре и перед операцией", "при усталости, бледности, одышке", "при температуре и других признаках инфекции", "во время беременности — по плану врача", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Не ешьте 8 часов до анализа, пить можно только чистую воду без газа. За сутки — без алкоголя.", "Детей до года не кормите 30–40 минут до анализа, от года до пяти лет — 2–3 часа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Врач смотрит на показатели вместе: один показатель редко даёт ответ. Сниженный гемоглобин может говорить об анемии, например из-за нехватки железа. Лейкоциты повышаются при инфекции и воспалении, а также после сильного стресса, у курящих. Небольшие отклонения часто не требуют лечения. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему у детей другие нормы?", "a": "Состав крови у детей меняется с возрастом, поэтому и нормы зависят от возраста. Результат ребёнка оценивает педиатр."}, {"q": "Почему в разных лабораториях разные нормы?", "a": "Нормы зависят от приборов и методов. Сравнивайте результат с нормой своего бланка, а для наблюдения лучше сдавать анализ в одной лаборатории."}], "together": ["20-003", "40-111", "40-081"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "20-003": {"lede": "Покажет, как быстро оседают эритроциты: по этому можно заметить воспаление в организме.", "blocks": [{"h": "Что это", "p": ["СОЭ — скорость оседания эритроцитов, красных клеток крови. В пробирке они постепенно опускаются на дно, а при воспалении в крови становится больше особых белков, эритроциты слипаются и оседают быстрее. Анализ помогает заметить воспаление, но не показывает, где оно и чем вызвано."]}, {"h": "Какие бывают признаки", "p": ["Сама СОЭ не ощущается. При воспалении, из-за которого она растёт, бывает:"], "list": ["температура без понятной причины", "боль и скованность в суставах", "боль в шее, плечах или в области таза", "головная боль, похудение без понятной причины"]}, {"h": "Когда назначают", "list": ["при температуре, слабости, болях в суставах", "вместе с общим анализом крови при диспансеризации и профосмотре", "чтобы следить за болезнями суставов и другими воспалительными болезнями", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Не ешьте 8 часов до анализа, пить можно только чистую воду без газа. За сутки — без алкоголя.", "Детей до года не кормите 30–40 минут до анализа, от года до пяти лет — 2–3 часа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенная СОЭ бывает при инфекциях, воспалении, болезнях суставов и почек. Умеренно повышают её и анемия, беременность, менструация, пожилой возраст; у женщин СОЭ обычно немного выше. Пониженная СОЭ встречается реже. Один показатель редко даёт ответ: врач смотрит на сочетание с другими анализами и жалобами. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем СОЭ отличается от С-реактивного белка?", "a": "Оба показывают воспаление. СРБ растёт и снижается быстрее, а СОЭ меняется медленно и может оставаться повышенной дольше."}, {"q": "СОЭ повышена, а чувствую себя хорошо. Что это значит?", "a": "СОЭ бывает повышена при анемии, беременности, с возрастом. Врач сравнит её с другими анализами и может попросить пересдать позже."}], "together": ["20-001", "40-081"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-052": {"lede": "Покажет, сколько железа в крови в момент анализа.", "blocks": [{"h": "Что это", "p": ["Железо нужно организму, чтобы делать гемоглобин — белок в эритроцитах, который переносит кислород. По крови железо возит особый белок — трансферрин. Анализ показывает, сколько железа в крови сейчас, а о запасах железа точнее говорит ферритин."]}, {"h": "Какие бывают признаки", "p": ["Если железа не хватает, бывает:"], "list": ["усталость и слабость", "бледность кожи", "одышка и сердцебиение при обычной нагрузке", "головная боль"], "note": "Избыток железа долго может ничем не ощущаться."}, {"h": "Когда назначают", "list": ["при усталости, бледности, одышке", "если гемоглобин в общем анализе крови снижен", "вместе с ферритином и ОЖСС — чтобы понять, хватает ли организму железа", "если врач подозревает избыток железа в организме", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Лучше сдавать утром. Не ешьте 2–3 часа до анализа, детей до года не кормите 30–40 минут. Пить можно чистую воду без газа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Если принимаете препараты железа, спросите врача, нужен ли перерыв перед анализом.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкое железо бывает при его нехватке, после кровопотери, при долгом воспалении. Высокое — при избытке железа в организме, после приёма его препаратов и гормональных противозачаточных. Уровень железа меняется в течение дня и после еды, поэтому один показатель редко даёт ответ: врач смотрит на сочетание с ферритином и ОЖСС. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем железо в крови отличается от ферритина?", "a": "Железо показывает, сколько его в крови сейчас, и меняется даже за день. Ферритин показывает запасы железа в организме."}, {"q": "Почему лучше сдавать утром?", "a": "Уровень железа меняется в течение дня. Если сдавать в одно и то же время, результаты проще сравнивать между собой."}], "together": ["40-111", "40-060.", "20-001"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-060.": {"lede": "Покажет, сколько железа может перенести кровь и сколько железа в ней сейчас.", "blocks": [{"h": "Что это", "p": ["Железо нужно для гемоглобина, который переносит кислород, а по крови железо возит белок трансферрин. ОЖСС — общая железосвязывающая способность — показывает, сколько железа могут связать белки крови, в основном трансферрин. В анализ входит и само железо в крови."]}, {"h": "Какие бывают признаки", "p": ["Если железа не хватает, бывает:"], "list": ["усталость и слабость", "бледность кожи", "одышка и сердцебиение при обычной нагрузке", "головная боль"]}, {"h": "Когда назначают", "list": ["если гемоглобин снижен и врач ищет причину", "вместе с ферритином — чтобы понять, хватает ли организму железа", "если врач подозревает избыток железа в организме", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, детей до года не кормите 30–40 минут. Пить можно чистую воду без газа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Если принимаете препараты железа, спросите врача, нужен ли перерыв перед анализом.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["При нехватке железа организм вырабатывает больше трансферрина, и ОЖСС обычно повышается. Повышается она и в конце беременности. Снижена ОЖСС бывает при избытке железа, воспалении, болезнях печени, нехватке белка в крови. Один показатель редко даёт ответ: врач смотрит на сочетание железа, ОЖСС и ферритина. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем ОЖСС, если есть анализ на железо?", "a": "Уровень железа меняется даже за день. Вместе с ОЖСС врач видит не только, сколько железа в крови, но и сколько его кровь может перенести."}, {"q": "Что значит «включая Fe» в названии?", "a": "Fe — химическое обозначение железа. Железо в крови уже входит в этот анализ."}], "together": ["40-111", "40-062", "20-001"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-062": {"lede": "Покажет, какая часть белка-переносчика железа сейчас занята железом.", "blocks": [{"h": "Что это", "p": ["Железо нужно для гемоглобина, который переносит кислород. По крови железо возит белок трансферрин: часть «мест» в нём занята железом, часть свободна. Коэффициент насыщения показывает, какая доля мест занята; его рассчитывают по железу в крови и ОЖСС."]}, {"h": "Какие бывают признаки", "p": ["Если железа не хватает, бывает:"], "list": ["усталость и слабость", "бледность кожи", "одышка и сердцебиение при обычной нагрузке", "головная боль"], "note": "Избыток железа долго может ничем не ощущаться."}, {"h": "Когда назначают", "list": ["вместе с ферритином — чтобы понять, хватает ли организму железа", "если гемоглобин в общем анализе крови снижен", "если врач подозревает избыток железа в организме", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Подготовка — как к анализу на железо: не ешьте 2–3 часа, пить можно чистую воду без газа. Точные правила уточните у администратора.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Если принимаете препараты железа, спросите врача, нужен ли перерыв перед анализом.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий коэффициент чаще всего бывает при нехватке железа, иногда — при долгом воспалении. Высокий — при избытке железа в организме и после приёма его препаратов. Результат меняется вслед за уровнем железа, в том числе в течение дня. Один показатель редко даёт ответ: врач оценивает его вместе с ферритином и может попросить пересдать анализ. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем коэффициент насыщения отличается от ферритина?", "a": "Коэффициент показывает, сколько железа кровь переносит сейчас, а ферритин — сколько железа хранится про запас. Вместе они дают врачу более полную картину."}, {"q": "Высокий коэффициент — это обязательно болезнь?", "a": "Нет. Он бывает высоким после еды и после приёма препаратов железа. Врач может попросить пересдать анализ и добавить ферритин."}], "together": ["40-111", "40-060.", "40-052"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-041": {"lede": "Покажет, хватает ли организму витамина B12, нужного для крови и нервной системы.", "blocks": [{"h": "Что это", "p": ["Витамин B12 нужен, чтобы в костном мозге созревали эритроциты и правильно работали нервы. С едой он поступает в основном из мяса, рыбы, яиц и молочных продуктов. Анализ показывает, сколько витамина B12 в крови."]}, {"h": "Какие бывают признаки", "p": ["Если витамина B12 не хватает, бывает:"], "list": ["усталость, слабость, одышка", "красный болезненный язык, язвочки во рту", "онемение и покалывание в руках и ногах", "неустойчивость при ходьбе, проблемы с памятью"], "note": "Обычно они появляются постепенно."}, {"h": "Когда назначают", "list": ["если в анализе крови снижен гемоглобин или эритроциты крупнее обычного", "при онемении и покалывании в руках и ногах", "при питании без мяса, рыбы, яиц и молочного", "после операций на желудке или кишечнике, при плохом усвоении пищи", "при долгом приёме некоторых лекарств, например от диабета"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, детей до года не кормите 30–40 минут. Пить можно чистую воду без газа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Скажите врачу, какие витамины и добавки принимаете и были ли уколы витамина B12.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий B12 бывает, когда его мало в еде или он плохо усваивается — из-за болезней желудка, кишечника, некоторых лекарств. Высокий чаще всего связан с приёмом витаминов или уколами. Один показатель редко даёт ответ: врач смотрит на сочетание с общим анализом крови. Нужно ли принимать витамин и в какой дозе, решает врач. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Я не ем мясо и молочное. Нужно ли сдавать B12?", "a": "Обсудите это с врачом. Без продуктов животного происхождения витамина B12 может не хватать — врач решит, нужен ли анализ."}, {"q": "Можно ли сдавать анализ, если я уже пью витамины?", "a": "Можно, но скажите о них врачу: витамины и уколы B12 повышают результат, и врачу нужно это учесть."}], "together": ["40-123", "20-001", "40-104"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-123": {"lede": "Покажет, хватает ли организму фолиевой кислоты — витамина, нужного для крови.", "blocks": [{"h": "Что это", "p": ["Фолиевая кислота — это витамин B9. Он нужен, чтобы клетки правильно делились: при его нехватке эритроциты созревают неправильно, а в начале беременности он важен для развития нервной системы ребёнка. Анализ показывает, сколько фолиевой кислоты в крови."]}, {"h": "Какие бывают признаки", "p": ["Если фолиевой кислоты не хватает, бывает:"], "list": ["усталость и слабость", "одышка и сердцебиение при обычной нагрузке", "красный болезненный язык, язвочки во рту", "головная боль, снижение аппетита"], "note": "Обычно они появляются постепенно."}, {"h": "Когда назначают", "list": ["если в анализе крови снижен гемоглобин или эритроциты крупнее обычного", "вместе с анализом на витамин B12 — их нехватка проявляется похоже", "при болезнях кишечника, когда пища плохо усваивается", "при приёме лекарств, которые мешают усвоению фолиевой кислоты"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, детей до года не кормите 30–40 минут. Пить можно чистую воду без газа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Скажите врачу, какие витамины и добавки принимаете.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий уровень может быть связан с нехваткой в питании, плохим усвоением в кишечнике, некоторыми лекарствами или алкоголем. Высокий обычно бывает при приёме витаминов. Один показатель редко даёт ответ: врач смотрит на сочетание с общим анализом крови и витамином B12. Нужно ли принимать витамин и в какой дозе, решает врач. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем сдавать вместе с витамином B12?", "a": "Нехватка этих витаминов проявляется похоже, а причины и лечение у неё разные. Поэтому врач обычно проверяет оба."}, {"q": "Влияют ли витамины на результат?", "a": "Да. Фолиевая кислота есть во многих поливитаминах и повышает результат. Скажите врачу, что и когда вы принимали."}], "together": ["40-041", "20-001"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "25-018": {"lede": "Покажет группу крови и резус-фактор — их важно знать при беременности, операции, переливании крови.", "blocks": [{"h": "Что это", "p": ["Группа крови зависит от особых меток — антигенов — на поверхности эритроцитов. Групп четыре: первая (0), вторая (A), третья (B) и четвёртая (AB).", "Резус-фактор — ещё одна такая метка: если она есть, резус положительный, если нет — отрицательный. Группа и резус передаются от родителей и не меняются в течение жизни."]}, {"h": "Какие бывают признаки", "p": ["Группа крови и резус никак не ощущаются: это не болезнь, а особенность крови. Узнать их можно только по анализу."], "note": "Знать их важно заранее: при переливании кровь донора должна подходить по группе и резусу, а при беременности врачу нужно знать резус мамы."}, {"h": "Когда назначают", "list": ["при планировании беременности и постановке на учёт", "будущему отцу, если у беременной резус отрицательный", "перед плановой операцией или госпитализацией", "если может понадобиться переливание крови"]}, {"h": "Как подготовиться", "list": ["Не ешьте 8 часов до анализа, пить можно только чистую воду без газа. За сутки — без алкоголя.", "Детей до года не кормите 30–40 минут до анализа, от года до пяти лет — 2–3 часа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["В бланке будет группа крови и резус — положительный или отрицательный. Ни одна группа и ни один резус не лучше других. Если у беременной резус отрицательный, а у ребёнка положительный, у мамы могут появиться антитела к эритроцитам ребёнка. Поэтому врач проверит резус будущего отца и при необходимости антитела. Нормы у этого анализа нет: в бланке лаборатория указывает группу и резус."]}], "faq": [{"q": "Меняется ли группа крови с возрастом?", "a": "Нет. Группа и резус передаются от родителей и не меняются в течение жизни."}, {"q": "Нужно ли снова сдавать анализ перед переливанием?", "a": "Да. Перед переливанием в больнице группу крови и её совместимость с кровью донора проверяют заново."}], "together": ["20-001", "80-049", "40-047"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "10.105": {"lede": "Покажет, как лейкоциты делятся по видам: их считают под микроскопом.", "blocks": [{"h": "Что это", "p": ["Лейкоциты — белые клетки крови, которые защищают организм. Они бывают разных видов, и у каждого своя работа:"], "list": ["нейтрофилы — первыми борются с микробами, особенно с бактериями", "лимфоциты — борются с вирусами и «запоминают» инфекции", "моноциты — уничтожают микробы и убирают погибшие клетки", "эозинофилы — защищают от паразитов, участвуют в аллергии", "базофилы — участвуют в аллергических реакциях"], "note": "Анализ показывает долю каждого вида. Лейкоциты считают под микроскопом."}, {"h": "Какие бывают признаки", "p": ["Изменения в формуле сами не ощущаются. Её проверяют, если бывает:"], "list": ["температура и другие признаки инфекции", "частые или затяжные инфекции", "аллергия: сыпь, зуд, насморк", "увеличенные лимфоузлы"]}, {"h": "Когда назначают", "list": ["если лейкоциты в общем анализе крови повышены или понижены", "при температуре и других признаках инфекции", "при приёме лекарств, которые могут влиять на кровь", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Приходите натощак, пить можно чистую воду без газа.", "За сутки не курите и не пейте алкоголь.", "За 30 минут избегайте нагрузок, посидите спокойно.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Нейтрофилов часто становится больше при бактериальной инфекции, лимфоцитов — при вирусной, эозинофилов — при аллергии и паразитах. Соотношение меняется и без болезни: после сильного стресса, у курящих, а у детей оно другое, чем у взрослых. Один показатель редко даёт ответ: врач смотрит на сочетание. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем лейкоформула отличается от общего анализа крови?", "a": "Общий анализ показывает, сколько всего лейкоцитов. Лейкоформула уточняет, какие они и в каком соотношении."}, {"q": "Зачем считать под микроскопом, если есть прибор?", "a": "Под микроскопом специалист видит не только число клеток, но и их форму, в том числе молодые клетки. Это дополняет подсчёт на приборе."}], "together": ["20-001", "20-003", "40-081"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-081": {"lede": "Покажет, есть ли в организме воспаление, и поможет следить за ним во время лечения.", "blocks": [{"h": "Что это", "p": ["С-реактивный белок (СРБ) — белок воспаления. Его вырабатывает печень: при инфекции, травме или другом воспалении уже через несколько часов его в крови становится больше. Анализ показывает, есть ли в организме воспаление, но не говорит, где оно и чем вызвано."]}, {"h": "Какие бывают признаки", "p": ["Сам СРБ не ощущается. При воспалении, из-за которого он растёт, бывает:"], "list": ["температура, озноб", "слабость, ломота в теле", "боль, отёк или покраснение в каком-то месте", "боль и скованность в суставах"]}, {"h": "Когда назначают", "list": ["при температуре и других признаках инфекции", "после операции — чтобы следить, нет ли инфекции", "при долгих воспалительных болезнях, например суставов или кишечника", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, детей до года не кормите 30–40 минут. Пить можно чистую воду без газа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Скажите врачу, если недавно болели, были травма или операция: это повышает СРБ.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный СРБ говорит о воспалении, но не о его причине. Немного повышать его могут лишний вес, курение, поздние сроки беременности, гормональные противозачаточные. Когда воспаление проходит, СРБ снижается, поэтому врач может попросить пересдать анализ. Одно отклонение — ещё не диагноз: врач оценивает показатель вместе с другими анализами. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем СРБ отличается от СОЭ?", "a": "Оба показывают воспаление. СРБ растёт и снижается быстрее, поэтому по нему удобно следить за лечением. СОЭ меняется медленнее."}, {"q": "Когда пересдать СРБ после болезни?", "a": "СРБ снижается быстро, когда воспаление проходит. Когда пересдать анализ, подскажет врач."}], "together": ["20-001", "20-003", "40-111"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-070": {"lede": "Покажет, сколько холестерина в крови, — первый шаг в оценке риска для сердца и сосудов.", "blocks": [{"h": "Что это", "p": ["Холестерин — жироподобное вещество. Он нужен для строительства клеток и выработки гормонов, большую часть его делает печень.", "Когда холестерина слишком много, он откладывается в стенках сосудов бляшками и сужает их. Анализ показывает весь холестерин крови сразу, без деления на части."]}, {"h": "Какие бывают признаки", "p": ["Высокий холестерин обычно никак не ощущается — узнать о нём можно только по анализу."], "note": "Поэтому его проверяют и без жалоб, особенно если в семье были болезни сердца."}, {"h": "Когда назначают", "list": ["при профилактическом осмотре и диспансеризации", "если у родственников был ранний инфаркт или очень высокий холестерин", "при высоком давлении, диабете, лишнем весе, курении", "детям — если у родителей очень высокий холестерин", "при приёме лекарств, снижающих холестерин"]}, {"h": "Как подготовиться", "list": ["За 2–3 часа до анализа не ешьте, чистую воду без газа пить можно. Ребёнка до года не кормите 30–40 минут.", "За 30 минут не курите, избегайте физического и эмоционального напряжения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Холестерин бывает выше из-за наследственности, питания, лишнего веса, сниженной работы щитовидной железы, при беременности и от некоторых лекарств. Низкий встречается реже, например при болезнях печени. Врач оценивает результат вместе с возрастом, давлением, курением и сахаром. Целевые значения назначает врач — они зависят от вашего общего риска. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Хватит ли только общего холестерина?", "a": "Для первой проверки часто хватает. Чтобы точнее оценить риск, врач может назначить липидный профиль: в нём есть ЛПНП, ЛПВП и триглицериды."}, {"q": "Как часто проверять холестерин?", "a": "Решает врач — по возрасту, здоровью, наследственности и прошлым результатам."}], "together": ["00-014", "40-047", "30-010"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-069": {"lede": "Покажет уровень триглицеридов — жиров крови, от которых зависит здоровье сосудов.", "blocks": [{"h": "Что это", "p": ["Триглицериды — самый частый вид жиров в организме. Они приходят с едой и вырабатываются печенью, а потом запасаются в жировой ткани как источник энергии.", "Когда их в крови много, повышается риск сужения сосудов. Анализ показывает, сколько триглицеридов в крови в момент сдачи."]}, {"h": "Какие бывают признаки", "p": ["Повышенные триглицериды обычно никак не ощущаются — узнать о них можно только по анализу."], "note": "Поэтому их проверяют и без жалоб, чаще вместе с холестерином."}, {"h": "Когда назначают", "list": ["при плановой проверке — обычно вместе с холестерином", "при лишнем весе, диабете, высоком давлении", "если у родственников были ранние болезни сердца", "при приёме лекарств, которые влияют на жиры крови"]}, {"h": "Как подготовиться", "list": ["За 2–3 часа до анализа не ешьте, чистую воду без газа пить можно. Ребёнка до года не кормите 30–40 минут.", "За 30 минут не курите, избегайте физического и эмоционального напряжения.", "Накануне — без алкоголя и жирной еды. Если триглицериды раньше были повышены, спросите врача, не сдать ли строго натощак.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Триглицериды временно растут после еды, особенно жирной и сладкой, и после алкоголя. Повышение бывает при лишнем весе, диабете, сниженной работе щитовидной железы, болезнях почек, при беременности и от некоторых лекарств. Очень высокие триглицериды повышают риск воспаления поджелудочной железы. Целевые значения назначает врач — они зависят от вашего общего риска. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему триглицериды выросли после праздника?", "a": "После жирной еды и алкоголя они временно повышаются. Врач может попросить пересдать анализ, когда питание будет обычным."}, {"q": "Чем триглицериды отличаются от холестерина?", "a": "Это разные жиры крови. Триглицериды — запас энергии, холестерин — материал для клеток и гормонов. Врач смотрит на оба."}], "together": ["00-014", "40-047", "30-010"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-044": {"lede": "Покажет общий холестерин, ЛПВП и их соотношение — для оценки риска для сосудов.", "blocks": [{"h": "Что это", "p": ["Холестерин переносится по крови в частицах — липопротеинах. ЛПВП собирают лишний холестерин и уносят его в печень, а остальные частицы, прежде всего ЛПНП, при избытке оставляют его в стенках сосудов.", "В анализ входят общий холестерин и ЛПВП. По ним рассчитывают индекс атерогенности — во сколько раз холестерина в остальных частицах больше, чем в ЛПВП. Атерогенный значит «способствующий образованию бляшек»."]}, {"h": "Какие бывают признаки", "p": ["Нарушения жиров крови обычно никак не ощущаются — узнать о них можно только по анализу."], "note": "Поэтому их проверяют и без жалоб — по плану врача."}, {"h": "Когда назначают", "list": ["взрослым старше 40 лет — чтобы оценить риск для сердца и сосудов", "если у родственников был ранний инфаркт или инсульт", "при высоком давлении, диабете, лишнем весе, курении", "при приёме лекарств, снижающих холестерин"]}, {"h": "Как подготовиться", "list": ["Обычно натощак: после еды 8–12 часов, воду пить можно. Если триглицериды раньше были повышены — строго натощак.", "Накануне — без алкоголя и жирной еды, за час до анализа не курите.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Индекс бывает выше, когда общий холестерин повышен или ЛПВП снижены. ЛПВП бывают ниже при курении, лишнем весе, малой подвижности и диабете. Индекс — расчётный показатель, поэтому врач смотрит и на сами значения и может назначить полный липидный профиль. Целевые значения назначает врач — они зависят от вашего общего риска. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем индекс отличается от липидного профиля?", "a": "Здесь только общий холестерин и ЛПВП. В липидный профиль обычно входят ещё ЛПНП и триглицериды — он даёт врачу больше сведений."}, {"q": "Почему ЛПВП называют «хорошим» холестерином?", "a": "Потому что ЛПВП уносят лишний холестерин из тканей в печень. Но и их врач оценивает вместе с другими показателями."}], "together": ["00-014", "40-069", "40-047"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "19.115": {"lede": "Покажет уровень Лп(а) — частиц с холестерином, уровень которых во многом задан наследственностью.", "blocks": [{"h": "Что это", "p": ["Липопротеин(а), или Лп(а), — частица, которая переносит холестерин по крови. Она похожа на ЛПНП, но легче задерживается в стенках сосудов и помогает расти бляшкам.", "Уровень Лп(а) во многом задан наследственностью и мало меняется в течение жизни. Анализ помогает врачу понять, повышен ли этот фактор риска."]}, {"h": "Какие бывают признаки", "p": ["Повышенный Лп(а) обычно никак не ощущается — узнать о нём можно только по анализу."], "note": "Питание и физическая активность на его уровень почти не влияют."}, {"h": "Когда назначают", "list": ["если у родственников рано были инфаркт или инсульт", "если у родственников нашли высокий Лп(а)", "если болезни сердца или сосудов начались в молодом возрасте", "при очень высоком холестерине — чтобы полнее оценить риск"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, воду пить можно.", "За час до анализа не курите.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Высокий Лп(а) повышает риск болезней сердца и сосудов, особенно если повышен и ЛПНП. Но это не значит, что болезнь обязательно будет. Врач учитывает Лп(а) вместе с возрастом, давлением, холестерином, сахаром и курением. У женщин после менопаузы уровень может немного вырасти. Целевые значения назначает врач — они зависят от вашего общего риска. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Нужно ли сдавать Лп(а) каждый год?", "a": "Обычно нет: уровень мало меняется с годами, и часто хватает одного анализа. Нужно ли повторить, решит врач."}, {"q": "Можно ли снизить Лп(а) питанием?", "a": "Питание и спорт на него почти не влияют. Но они помогают снизить другие факторы риска — что делать, обсудите с врачом."}], "together": ["00-014", "19.105"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "19.100": {"lede": "Покажет уровень белка, который помогает уносить лишний холестерин из тканей в печень.", "blocks": [{"h": "Что это", "p": ["Аполипопротеины — белки, из которых построены частицы, переносящие жиры по крови. Аполипопротеин А1 — главный белок ЛПВП: частиц, которые собирают лишний холестерин в тканях и уносят его в печень.", "Анализ показывает, сколько этого белка в крови. Врач использует его как дополнительный показатель, когда оценивает риск для сердца и сосудов."]}, {"h": "Какие бывают признаки", "p": ["Изменения аполипопротеина А1 обычно никак не ощущаются — узнать о них можно только по анализу."], "note": "Поэтому его проверяют без жалоб, по назначению врача."}, {"h": "Когда назначают", "list": ["если у родственников были ранние болезни сердца или сосудов", "при повышенном холестерине — чтобы точнее оценить риск", "если в липидном профиле очень низкие ЛПВП", "чтобы проверить, как действует лечение"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа, чистую воду пить можно.", "За 30 минут не курите, избегайте физического и эмоционального напряжения.", "Если утром нужно принять лекарства, заранее спросите врача, можно ли сделать это после анализа.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий аполипопротеин А1 обычно идёт вместе с низкими ЛПВП: лишний холестерин выводится хуже, риск для сосудов выше. Он бывает ниже при курении, плохо контролируемом диабете, болезнях почек и печени. Повышение редко бывает проблемой — например, при регулярных нагрузках, беременности. Целевые значения назначает врач — они зависят от вашего общего риска. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему этот анализ назначают реже липидного профиля?", "a": "Обычно хватает липидного профиля. Аполипопротеин А1 врач добавляет, когда нужно уточнить риск."}, {"q": "Зачем сдавать вместе с аполипопротеином B?", "a": "Врач может сравнить два показателя: их соотношение помогает точнее оценить риск для сосудов."}], "together": ["19.105", "00-014"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "19.105": {"lede": "Покажет, сколько в крови частиц, которые переносят холестерин и могут оседать в сосудах.", "blocks": [{"h": "Что это", "p": ["Аполипопротеин B — белок, на котором держатся частицы, переносящие холестерин и другие жиры к органам: ЛПНП и похожие на них. В каждой такой частице по одной молекуле этого белка.", "Поэтому анализ показывает, сколько в крови частиц, которые при избытке оседают в стенках сосудов и образуют бляшки."]}, {"h": "Какие бывают признаки", "p": ["Повышенный аполипопротеин B обычно никак не ощущается — узнать о нём можно только по анализу."], "note": "Поэтому его проверяют без жалоб, по назначению врача."}, {"h": "Когда назначают", "list": ["если у родственников были ранние болезни сердца или сосудов", "при повышенном холестерине или триглицеридах — чтобы точнее оценить риск", "при диабете, лишнем весе — по решению врача", "чтобы проверить, как действует лечение, снижающее холестерин"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа, чистую воду пить можно.", "За 30 минут не курите, избегайте физического и эмоционального напряжения.", "Если утром нужно принять лекарства, заранее спросите врача, можно ли сделать это после анализа.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный аполипопротеин B обычно идёт вместе с высоким ЛПНП и говорит о повышенном риске атеросклероза — сужения сосудов бляшками. Он бывает выше при диабете, сниженной работе щитовидной железы, болезнях почек, при беременности и от некоторых лекарств. Врач может сравнить его с аполипопротеином А1. Целевые значения назначает врач — они зависят от вашего общего риска. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем аполипопротеин B отличается от ЛПНП?", "a": "ЛПНП показывает, сколько холестерина в частицах, а аполипопротеин B — сколько самих частиц. Иногда это даёт врачу дополнительные сведения."}, {"q": "Можно ли утром выпить таблетки?", "a": "Заранее спросите врача, можно ли принять их после анализа. Если отложить нельзя — скажите об этом медсестре."}], "together": ["19.100", "00-014", "19.115"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-104": {"lede": "Покажет уровень гомоцистеина — вещества, которое копится при нехватке витаминов B12, B6 и фолиевой кислоты.", "blocks": [{"h": "Что это", "p": ["Гомоцистеин — аминокислота, которая образуется в организме при обмене белков. Обычно она быстро превращается в другие нужные вещества, и для этого нужны витамины B12, B6 и фолиевая кислота.", "Если витаминов не хватает или обмен нарушен, гомоцистеин накапливается. Его избыток может повреждать стенки сосудов и повышать склонность к тромбам. Анализ показывает, сколько гомоцистеина в крови."]}, {"h": "Какие бывают признаки", "p": ["Сам гомоцистеин не ощущается. Если причина — нехватка витамина B12 или фолиевой кислоты, бывает:"], "list": ["усталость и слабость", "головокружение, сердцебиение", "бледность кожи", "язвочки во рту, воспалённый язык", "онемение или покалывание в руках и ногах"]}, {"h": "Когда назначают", "list": ["при подозрении на нехватку витамина B12 или фолиевой кислоты", "пожилым людям и при скудном питании — по решению врача", "если уже были инфаркт, инсульт или тромбоз, особенно в молодом возрасте", "при высоком давлении, повышенном холестерине, диабете — для оценки риска"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, воду пить можно.", "Скажите врачу, если принимаете витамины группы B или фолиевую кислоту: они снижают гомоцистеин.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный гомоцистеин часто связан с нехваткой витаминов B12 или фолиевой кислоты. Он бывает выше при болезнях почек, сниженной работе щитовидной железы, с возрастом и от некоторых лекарств, редко — из-за наследственных нарушений обмена. Повышение связывают с риском для сосудов, но само по себе оно болезнь не доказывает. Врач оценивает результат вместе с другими анализами. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Нужно ли проверять гомоцистеин всем для профилактики?", "a": "Нет, всем подряд его не сдают. Врач назначает анализ, если подозревает нехватку витаминов или оценивает риск для сосудов."}, {"q": "Почему врач назначил ещё B12 и фолиевую кислоту?", "a": "Гомоцистеин повышается при нехватке этих витаминов. Их анализы помогают врачу понять причину."}], "together": ["40-041", "40-123", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-080": {"lede": "Покажет, не работает ли сердце с перегрузкой, — помогает врачу проверить, нет ли сердечной недостаточности.", "blocks": [{"h": "Что это", "p": ["Когда сердцу приходится работать с перегрузкой и его стенки растягиваются, оно выделяет в кровь гормон BNP. NT-proBNP — неактивная часть, которая образуется вместе с ним.", "Анализ помогает врачу понять, связаны ли одышка, отёки и усталость с сердечной недостаточностью — состоянием, когда сердце не справляется с перекачиванием крови.", "При внезапной боли в груди, сильной одышке вызывайте скорую помощь — не ждите анализа."]}, {"h": "Какие бывают признаки", "p": ["При сердечной недостаточности бывает:"], "list": ["одышка при обычной нагрузке или лёжа", "отёки ног и лодыжек", "быстрая усталость и слабость", "кашель, особенно ночью"], "note": "Похожие признаки бывают и при болезнях лёгких."}, {"h": "Когда назначают", "list": ["при одышке, отёках, быстрой усталости — чтобы проверить сердце", "если сердечная недостаточность уже есть — чтобы оценить её течение", "после инфаркта и при других болезнях сердца — по решению врача"]}, {"h": "Как подготовиться", "list": ["Особой подготовки не нужно. Если в этот день сдаёте и другие анализы, следуйте их правилам.", "Скажите врачу, какие лекарства от давления и для сердца вы принимаете: некоторые из них снижают NT-proBNP.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Нормальный NT-proBNP у человека с одышкой обычно делает сердечную недостаточность маловероятной. Повышение может говорить о перегрузке сердца, но бывает и при нарушениях ритма, болезнях почек, тяжёлых инфекциях, а с возрастом уровень растёт и без болезни. При лишнем весе он может быть ниже. Диагноз ставят после УЗИ сердца и осмотра, результат оценивает врач. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Можно ли сдать NT-proBNP вместо УЗИ сердца?", "a": "Нет. Анализ помогает врачу решить, нужно ли дальнейшее обследование, но не заменяет УЗИ сердца и осмотр."}, {"q": "Почему важен возраст?", "a": "С годами NT-proBNP постепенно растёт и у здоровых людей, поэтому врач учитывает возраст, когда оценивает результат."}], "together": ["40-063", "40-018.1", "20-017"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "17.130": {"lede": "Покажет, повышен ли тропонин — белок, который попадает в кровь при повреждении сердечной мышцы.", "blocks": [{"h": "Что это", "p": ["Тропонин I — белок клеток сердечной мышцы. Когда эти клетки повреждаются, например при инфаркте, тропонин выходит в кровь и его уровень растёт.", "Это анализ для врача при подозрении на повреждение сердца, а не для планового чек-апа. При острых жалобах тропонин определяют в больнице, повторно через несколько часов.", "При внезапной боли в груди, сильной одышке вызывайте скорую помощь — не ждите анализа."]}, {"h": "Какие бывают признаки", "p": ["При повреждении сердечной мышцы бывает:"], "list": ["боль, давление или жжение в груди", "боль, которая отдаёт в руку, плечо, шею, челюсть или спину", "одышка", "холодный пот, тошнота, головокружение"], "note": "Боль при инфаркте бывает и несильной, похожей на изжогу."}, {"h": "Когда назначают", "list": ["по направлению врача — при подозрении на повреждение сердечной мышцы", "при подозрении на миокардит — воспаление сердечной мышцы", "до и после операций или лечения, которые могут повлиять на сердце"]}, {"h": "Как подготовиться", "list": ["Особой подготовки не нужно.", "Если принимаете биотин (витамин B7), например в добавках для волос и ногтей, скажите врачу: он может занизить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный тропонин говорит о повреждении клеток сердечной мышцы. Причиной бывает инфаркт, а также миокардит, нарушения ритма, сердечная недостаточность, болезни почек, тяжёлая инфекция и даже очень долгая нагрузка, например марафон. Тропонин растёт не сразу после начала боли, поэтому один нормальный результат не всегда исключает проблему. Причину определяет врач. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Можно ли сдать тропонин для профилактики?", "a": "Нет, это не анализ для чек-апа. Его назначает врач, если подозревает повреждение сердечной мышцы."}, {"q": "Болит в груди — можно сначала сдать тропонин?", "a": "Нет. При внезапной боли в груди вызывайте скорую: в больнице сделают ЭКГ и анализ на тропонин сразу и повторно."}], "together": ["40-080", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-077": {"lede": "Покажет, как почки выводят мочевину — отработанное вещество, которое остаётся от белков.", "blocks": [{"h": "Что это", "p": ["Мочевина образуется в печени, когда организм перерабатывает белки. Это отработанное вещество: почки выводят его из крови с мочой.", "Если почки работают хуже, мочевины в крови становится больше. Поэтому анализ помогает оценить работу почек — обычно вместе с креатинином."]}, {"h": "Какие бывают признаки", "p": ["В начале болезни почек жалоб обычно нет. Позже бывает:"], "list": ["отёки на лице, руках или ногах", "мочи стало меньше или больше обычного, особенно ночью", "слабость, усталость, плохой аппетит", "плохой сон, трудно сосредоточиться"], "note": "Поэтому при диабете и высоком давлении работу почек проверяют и без жалоб."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии вместе с креатинином", "при отёках, изменении количества мочи, слабости без причины", "при диабете, высоком давлении, болезнях сердца", "при приёме лекарств, которые могут влиять на почки", "при болезнях почек — чтобы следить за их работой"]}, {"h": "Как подготовиться", "list": ["Утром натощак: не ешьте 12 часов, чистую воду без газа пить можно.", "Детям до года — не кормить 30–40 минут, от года до пяти лет — 2–3 часа.", "За 30 минут — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенная мочевина может говорить о том, что почки хуже очищают кровь. Но она растёт и без болезни почек: при обезвоживании, когда в еде много белка, от некоторых лекарств, с возрастом. Низкая бывает при беременности, нехватке белка в питании, болезнях печени. Одно отклонение — ещё не диагноз: врач оценит мочевину вместе с креатинином и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем мочевина отличается от креатинина?", "a": "Оба вещества выводят почки. Но мочевина сильнее зависит от еды, питья и работы печени, поэтому врач обычно смотрит их вместе."}, {"q": "Мочевина повышена. Это болезнь почек?", "a": "Не обязательно. Она растёт и при обезвоживании, белковой еде, от некоторых лекарств. Врач оценит её вместе с креатинином и может попросить пересдать."}], "together": ["40-063", "10-008", "40-018.1"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "17.167": {"lede": "Покажет, как почки очищают кровь, — по белку, на который мало влияют мышцы и питание.", "blocks": [{"h": "Что это", "p": ["Цистатин С — небольшой белок, который почти все клетки организма вырабатывают с постоянной скоростью. Почки убирают его из крови, и если они работают хуже, цистатина С становится больше.", "В отличие от креатинина, на него мало влияют мышцы, мясо в еде и возраст."]}, {"h": "Какие бывают признаки", "p": ["Когда почки начинают работать хуже, это обычно никак не ощущается — заметить можно только по анализам."], "note": "Поэтому работу почек проверяют и без жалоб: при диабете, высоком давлении, болезнях сердца."}, {"h": "Когда назначают", "list": ["если креатинин может ошибаться: при очень большой или очень малой мышечной массе", "пожилым, при сильной худобе, после ампутации, при циррозе печени", "если по креатинину работа почек на границе нормы", "чтобы следить за работой почек со временем"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, чистую воду без газа пить можно.", "За час до анализа не курите: курение может повысить цистатин С.", "Скажите врачу, если принимаете гормоны-глюкокортикоиды или есть болезни щитовидной железы: они могут изменить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный цистатин С может говорить о том, что почки хуже очищают кровь. Иногда он растёт и без болезни почек: от глюкокортикоидов, курения, воспаления, при усиленной работе щитовидной железы. По цистатину С врач может рассчитать СКФ — скорость, с которой почки очищают кровь. Одно отклонение — ещё не диагноз, врач может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем цистатин С, если креатинин уже сдан?", "a": "Креатинин зависит от мышц и питания. Цистатин С зависит от них меньше и помогает уточнить работу почек, когда креатинин может ошибаться."}, {"q": "Можно ли сдать его вместе с креатинином?", "a": "Да, их часто сдают вместе: по двум показателям СКФ рассчитывают точнее, чем по одному."}], "together": ["40-063", "40.120", "40-077"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-018.1": {"lede": "Покажет, хватает ли в крови солей, от которых зависит работа сердца, мышц и нервов.", "blocks": [{"h": "Что это", "p": ["Калий, натрий и хлор — соли крови, или электролиты: минералы, растворённые в крови и других жидкостях организма. Они нужны для работы мышц, сердца и нервов и помогают удерживать в теле нужное количество воды.", "Мы получаем их с едой и питьём, лишнее выводят почки, а анализ показывает, сколько каждой соли в крови."]}, {"h": "Какие бывают признаки", "p": ["Если солей в крови слишком мало или много, бывает:"], "list": ["слабость и быстрая усталость", "судороги, подёргивания или слабость в мышцах", "перебои в работе сердца, учащённое сердцебиение", "тошнота, рвота, головная боль", "спутанность мыслей, заторможенность"], "note": "Небольшие отклонения часто ничем не ощущаются."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии", "при сильной рвоте, поносе, обезвоживании", "при приёме мочегонных и лекарств от давления", "при болезнях почек, сердца, высоком давлении", "при слабости, судорогах в мышцах, перебоях в работе сердца"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, чистую воду без газа пить можно. Детей до года не кормите 30–40 минут.", "За 30 минут — без физических нагрузок, волнений и курения.", "Во время взятия крови не сжимайте кулак много раз: калий может оказаться выше настоящего.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Отклонения бывают при болезнях почек, сердца, надпочечников. Но часто причина проще: потеря жидкости при рвоте, поносе, жаре или приём лекарств, например мочегонных. Калий может оказаться выше настоящего, если при взятии крови часто сжимали кулак. Одно отклонение — ещё не диагноз: врач оценит соли крови вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем сдавать три показателя сразу?", "a": "Эти соли работают вместе и зависят от количества воды в организме и работы почек. По их сочетанию врачу проще понять причину отклонения."}, {"q": "Можно ли пить воду перед анализом?", "a": "Да, чистую воду без газа пить можно. Не ешьте за 2–3 часа до анализа и не курите за 30 минут."}], "together": ["40-063", "40-077"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-056": {"lede": "Покажет, хватает ли в крови калия, который нужен для работы сердца и мышц.", "blocks": [{"h": "Что это", "p": ["Калий — одна из солей крови. Он нужен, чтобы правильно работали сердце, мышцы и нервы.", "Почти весь калий находится внутри клеток, в крови его немного, а лишний выводят почки. Анализ показывает, сколько калия в крови."]}, {"h": "Какие бывают признаки", "p": ["Если калия слишком мало или много, бывает:"], "list": ["слабость в мышцах, быстрая усталость", "судороги или подёргивания мышц", "перебои в работе сердца", "тошнота", "запоры — чаще при нехватке калия"], "note": "Небольшие отклонения часто ничем не ощущаются."}, {"h": "Когда назначают", "list": ["при приёме мочегонных, лекарств от давления и для сердца", "при болезнях почек — чтобы следить за их работой", "при сильной рвоте и поносе", "при слабости в мышцах, судорогах, перебоях в работе сердца", "при плановой проверке — в составе биохимии"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, чистую воду без газа пить можно. Детей до года не кормите 30–40 минут.", "За 30 минут — без физических нагрузок, волнений и курения.", "Во время взятия крови не сжимайте кулак много раз: калий может оказаться выше настоящего.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Высокий калий бывает, когда почки хуже выводят его, а также от некоторых лекарств от давления и обезболивающих. Низкий — при рвоте, поносе, приёме мочегонных. Калий может оказаться выше настоящего, если при взятии крови часто сжимали кулак. Одно отклонение — ещё не диагноз: врач оценит калий вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Почему нельзя сжимать кулак при взятии крови?", "a": "Когда мышцы работают, калий выходит из клеток в кровь. В пробирке его окажется больше, чем на самом деле, и анализ могут попросить пересдать."}, {"q": "Принимаю мочегонные. Зачем проверять калий?", "a": "Одни мочегонные выводят калий, другие задерживают его в организме. Как часто проверять калий, решит врач."}], "together": ["40-057", "40-058", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-057": {"lede": "Покажет, хватает ли в крови натрия и не нарушен ли водный баланс организма.", "blocks": [{"h": "Что это", "p": ["Натрий — одна из солей крови, с едой мы получаем его в основном из поваренной соли. Он удерживает в организме нужное количество воды и нужен для работы нервов и мышц.", "Уровень натрия меняется, когда воды в теле становится слишком мало или много, поэтому анализ помогает оценить водный баланс."]}, {"h": "Какие бывают признаки", "p": ["Если натрия слишком мало или много, бывает:"], "list": ["слабость, усталость", "сильная жажда, мало мочи", "тошнота, рвота", "подёргивания мышц", "спутанность мыслей, заторможенность"], "note": "Если натрий меняется медленно, жалоб может не быть."}, {"h": "Когда назначают", "list": ["при рвоте, поносе, сильной потливости — когда есть риск обезвоживания", "при отёках", "при приёме мочегонных и других лекарств, влияющих на водный баланс", "при болезнях сердца, почек, печени", "при слабости и спутанности мыслей, особенно у пожилых"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, чистую воду без газа пить можно. Детей до года не кормите 30–40 минут.", "За 30 минут — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий натрий бывает при потере солей с рвотой, поносом, потом, при приёме мочегонных и когда в организме задерживается лишняя вода. Высокий почти всегда связан с нехваткой воды: человек мало пьёт или теряет много жидкости. На натрий влияют и некоторые лекарства. Одно отклонение — ещё не диагноз: врач оценит натрий вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Если есть много соли, натрий в крови повысится?", "a": "Обычно нет: организм держит натрий в узких пределах и выводит лишнее с мочой. Чаще натрий меняется из-за потери или избытка воды."}, {"q": "Сдавать натрий отдельно или вместе с калием и хлором?", "a": "Решает врач. Часто удобнее сдать комплекс — калий, натрий и хлор вместе: врач оценивает их в сочетании."}], "together": ["40-056", "40-058", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-058": {"lede": "Покажет, сколько в крови хлора — соли, которая помогает держать водный баланс.", "blocks": [{"h": "Что это", "p": ["Хлор — одна из солей крови. Вместе с натрием он входит в поваренную соль, помогает удерживать в организме нужное количество воды и поддерживать кислотно-щелочное равновесие — баланс кислот и щелочей в крови.", "Хлор обычно меняется вместе с натрием, поэтому их оценивают вместе."]}, {"h": "Какие бывают признаки", "p": ["Сам по себе хлор редко вызывает жалобы. Обычно он меняется при потере жидкости, и тогда бывает:"], "list": ["долгая рвота или понос", "жажда, сухость во рту, мало мочи", "слабость, усталость"]}, {"h": "Когда назначают", "list": ["вместе с натрием и калием — при плановой проверке", "при долгой рвоте или поносе, обезвоживании", "при болезнях почек, сердца, лёгких", "при приёме мочегонных", "если врачу нужно оценить кислотно-щелочное равновесие крови"]}, {"h": "Как подготовиться", "list": ["Не ешьте 2–3 часа до анализа, чистую воду без газа пить можно. Детей до года не кормите 30–40 минут.", "За 30 минут — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный хлор чаще бывает при обезвоживании, пониженный — при долгой рвоте, поносе, приёме мочегонных или большого количества средств от изжоги. Если хлор и натрий меняются по-разному, врач проверит, нет ли сдвига кислотно-щелочного равновесия. Одно отклонение — ещё не диагноз: врач оценит хлор вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Это тот же хлор, что в воде из-под крана?", "a": "Нет. В крови хлор находится в составе солей, и получаем мы его в основном из поваренной соли."}, {"q": "Нужно ли сдавать хлор отдельно?", "a": "Обычно его сдают вместе с калием и натрием — в комплексе. Отдельно назначают, если врачу нужно перепроверить только этот показатель."}], "together": ["40-057", "40-056", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40.120": {"lede": "Покажет, не теряют ли почки белок альбумин с мочой, — ещё до появления жалоб.", "blocks": [{"h": "Что это", "p": ["Альбумин — главный белок крови. Здоровые почки почти не пропускают его в мочу, а при их повреждении он начинает понемногу выходить с мочой — это называют микроальбуминурией.", "Для анализа сдают мочу, а не кровь. Он замечает даже малое количество альбумина и помогает увидеть изменения в почках рано."]}, {"h": "Какие бывают признаки", "p": ["Небольшая потеря альбумина с мочой обычно никак не ощущается — узнать о ней можно только по анализу."], "note": "Поэтому при диабете и высоком давлении анализ сдают и без жалоб, по плану врача."}, {"h": "Когда назначают", "list": ["при диабете — регулярно, по плану врача", "при высоком давлении", "при болезнях сердца и сосудов", "если креатинин или СКФ изменены", "при болезнях почек у близких родственников"]}, {"h": "Как подготовиться", "list": ["Правила сбора уточните у администратора: какую порцию мочи собрать и как хранить контейнер до сдачи.", "Накануне и в день сбора — без тяжёлых тренировок: нагрузка может временно повысить альбумин в моче.", "При температуре, инфекции мочевых путей и во время менструации предупредите врача: сбор обычно переносят.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный альбумин в моче может говорить о раннем повреждении почек, например при диабете или высоком давлении. Но он растёт и временно: после тяжёлой нагрузки, при температуре, инфекции мочевых путей, обезвоживании. Если мочу собрали не по правилам, анализ могут попросить пересдать. Одно отклонение — ещё не диагноз: повышенный результат врач обычно перепроверяет. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем этот анализ отличается от общего анализа мочи?", "a": "Общий анализ мочи замечает белок, когда его уже много. Этот анализ находит даже малое количество альбумина — раньше, чем изменения видны в общем анализе."}, {"q": "Почему анализ просят повторить?", "a": "Альбумин в моче может временно повышаться после нагрузки, при температуре или инфекции. Поэтому повышенный результат обычно подтверждают повторным анализом."}], "together": ["40-063", "40-141", "10-008"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-010": {"lede": "Покажет, нет ли признаков воспаления поджелудочной железы или слюнных желёз.", "blocks": [{"h": "Что это", "p": ["Альфа-амилаза — фермент, то есть вещество, которое помогает переваривать крахмал из еды. Её вырабатывают поджелудочная железа и слюнные железы, а в кровь в норме попадает немного.", "Когда поджелудочная воспаляется или её проток перекрыт, например камнем из желчного пузыря, амилазы в крови становится намного больше."]}, {"h": "Какие бывают признаки", "p": ["При воспалении поджелудочной железы бывает:"], "list": ["сильная боль в верхней части живота, которая может отдавать в спину", "тошнота и рвота", "повышенная температура", "плохой аппетит, общее недомогание"], "note": "При внезапной сильной боли в животе вызывайте скорую помощь — не ждите анализа."}, {"h": "Когда назначают", "list": ["при сильной боли в верхней части живота, особенно если она отдаёт в спину", "при боли в животе вместе с тошнотой и рвотой", "при болезнях желчного пузыря", "при припухлости и боли под ушами — в области слюнных желёз", "чтобы проследить, как идёт лечение поджелудочной железы"]}, {"h": "Как подготовиться", "list": ["Утром натощак: не ешьте 12 часов, чистую воду без газа пить можно.", "Детям до года — не кормить 30–40 минут, от года до пяти лет — 2–3 часа.", "За 30 минут — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Сильно повышенная амилаза часто бывает при воспалении поджелудочной железы. Повышение бывает и при болезнях желчного пузыря, воспалении слюнных желёз, когда почки хуже выводят амилазу, от некоторых лекарств, а иногда без болезни. При воспалении амилаза быстро снижается, поэтому нормальный результат его не всегда исключает. Одно отклонение — ещё не диагноз, врач может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Сильно болит живот. Сначала сдать анализ?", "a": "Нет. При внезапной сильной боли в животе вызывайте скорую помощь. Анализ не заменяет осмотр врача."}, {"q": "Амилаза повышена, а живот не болит. Почему?", "a": "Так бывает при болезнях почек, воспалении слюнных желёз, от некоторых лекарств, а иногда — без болезни. Причину выяснит врач."}], "together": ["40-026", "40-035", "40-081"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-025": {"lede": "Покажет, нет ли признаков повреждения клеток печени, а также мышц или сердца.", "blocks": [{"h": "Что это", "p": ["АСТ — фермент, то есть вещество, которое ускоряет реакции в клетках. Его много в печени и сердце, меньше — в мышцах.", "Когда эти клетки повреждаются, АСТ выходит в кровь, поэтому анализ, особенно вместе с АЛТ, помогает заметить проблемы с печенью."]}, {"h": "Какие бывают признаки", "p": ["Печень долго может не давать о себе знать. Иногда при её болезнях бывает:"], "list": ["слабость, быстрая утомляемость", "тошнота, плохой аппетит", "тяжесть или боль справа под рёбрами", "желтизна кожи и глаз, тёмная моча"], "note": "В начале болезни печени жалоб часто нет."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии крови", "при слабости, тошноте, желтизне кожи, тёмной моче", "при приёме лекарств, которые могут влиять на печень", "при лишнем весе, диабете, частом употреблении алкоголя", "при болезнях печени у родственников, после контакта с больным гепатитом"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа. Чистую воду без газа пить можно.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За несколько дней — без непривычно тяжёлых тренировок, за 30 минут — без нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий АСТ обычно считается нормой, а повышенный может говорить о повреждении клеток печени, мышц или сердца. Без болезни АСТ может временно вырасти после тяжёлой нагрузки, ушиба, укола в мышцу, от некоторых лекарств и травяных средств. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем АСТ отличается от АЛТ?", "a": "АЛТ находится в основном в печени, а АСТ — ещё в сердце и мышцах. Поэтому врач смотрит на них вместе: так проще понять причину повышения."}, {"q": "Можно ли сдавать АСТ после тренировки?", "a": "Лучше подождать несколько дней: после тяжёлой нагрузки АСТ может временно вырасти. Если недавно были травма или уколы в мышцу, скажите об этом врачу."}], "together": ["40-026", "21.120", "40-035"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "21.120": {"lede": "Покажет, нет ли признаков повреждения печени или желчных протоков.", "blocks": [{"h": "Что это", "p": ["ГГТ (гамма-глутамилтранспептидаза) — фермент, то есть вещество, которое ускоряет реакции в клетках. Он есть во многих органах, но больше всего — в печени.", "При повреждении печени или желчных протоков — трубочек, по которым оттекает желчь, — ГГТ выходит в кровь."]}, {"h": "Какие бывают признаки", "p": ["Печень долго может не давать о себе знать. Иногда при болезнях печени и желчных протоков бывает:"], "list": ["слабость, быстрая утомляемость", "тошнота, плохой аппетит", "сильный кожный зуд", "желтизна кожи и глаз, тёмная моча"], "note": "ГГТ может быть повышена и без всяких жалоб."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии крови", "если повышена щелочная фосфатаза — чтобы понять, печень это или кости", "при желтизне кожи, кожном зуде, тёмной моче", "при приёме лекарств, которые могут влиять на печень", "при частом употреблении алкоголя"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов, чистую воду пить можно.", "За сутки — без алкоголя: он может временно повысить ГГТ. За час до анализа не курите.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкая ГГТ обычно не беспокоит врачей, а повышенная может говорить о болезнях печени или желчных протоков — каких именно, анализ не показывает. Без болезни ГГТ временно повышают алкоголь накануне, курение и многие лекарства. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем ГГТ, если уже сдаю щелочную фосфатазу?", "a": "Щелочная фосфатаза повышается и при болезнях печени, и при болезнях костей. Если ГГТ тоже выше нормы, причина скорее в печени, если в норме — скорее в костях."}, {"q": "Накануне был алкоголь — можно сдавать ГГТ?", "a": "Лучше перенести анализ: алкоголь за сутки до сдачи может временно повысить ГГТ. Если всё же сдаёте, скажите об этом врачу."}], "together": ["40-121", "40-026", "40-025"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-121": {"lede": "Покажет, нет ли изменений в печени, желчных протоках или костях.", "blocks": [{"h": "Что это", "p": ["Щелочная фосфатаза — фермент, то есть вещество, которое ускоряет реакции в клетках. Больше всего его в печени, желчных протоках и костях — там его вырабатывают клетки, которые строят новую кость.", "Уровень в крови растёт, когда нарушается отток желчи или кости обновляются активнее обычного."]}, {"h": "Какие бывают признаки", "p": ["При болезнях печени или костей бывает:"], "list": ["желтизна кожи и глаз, тёмная моча, светлый кал", "кожный зуд", "боль справа под рёбрами, тошнота", "боль в костях, частые переломы"], "note": "Иногда жалоб нет совсем."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии крови", "при желтизне кожи, кожном зуде, тёмной моче, светлом кале", "при боли в костях, частых переломах", "если другие анализы печени отклонились от нормы", "чтобы следить за лечением болезней печени или костей"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа, чистую воду без газа пить можно: после еды фермент может немного вырасти.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За 30 минут до анализа — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Понижение встречается редко, а повышение может быть связано с печенью и оттоком желчи или с костями — источник врач уточнит по другим анализам. Без болезни щелочная фосфатаза выше у детей и подростков, пока растут кости, при беременности, когда срастается перелом, и от некоторых лекарств. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "У ребёнка щелочная фосфатаза выше, чем у взрослых, — это плохо?", "a": "Обычно нет: у детей и подростков растут кости, и фермента в крови больше. Поэтому результат ребёнка врач оценивает с учётом возраста."}, {"q": "Почему щелочная фосфатаза выросла при беременности?", "a": "Её вырабатывает и плацента, поэтому уровень растёт, особенно в последние месяцы беременности. Обычно это не болезнь, но результат оценивает врач."}], "together": ["21.120", "40-026", "40-297"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-035": {"lede": "Покажет, сколько в крови билирубина и справляется ли печень с его переработкой.", "blocks": [{"h": "Что это", "p": ["Билирубин — жёлтое вещество, которое образуется, когда организм обновляет эритроциты: старые разрушаются, на их место приходят новые. Печень перерабатывает билирубин и выводит его с желчью в кишечник.", "Если билирубина образуется слишком много или печень не успевает его вывести, он копится в крови — анализ показывает, сколько его всего."]}, {"h": "Какие бывают признаки", "p": ["Если билирубина в крови много, бывает:"], "list": ["желтизна кожи и белков глаз", "тёмная моча", "светлый кал", "кожный зуд"], "note": "Небольшое повышение может ничем не ощущаться. Если пожелтели кожа или белки глаз, не откладывайте визит к врачу."}, {"h": "Когда назначают", "list": ["при желтизне кожи или глаз, тёмной моче, светлом кале", "при плановой проверке — в составе биохимии крови", "при болезнях печени и желчного пузыря — чтобы следить за состоянием", "при анемии — чтобы проверить, не разрушаются ли эритроциты слишком быстро", "у младенцев с желтухой — по назначению педиатра"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа. Чистую воду без газа пить можно.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За 30 минут до анализа — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий билирубин обычно не беспокоит врачей, а повышенный бывает при болезнях печени, плохом оттоке желчи или когда эритроциты разрушаются быстрее обычного. Повышение бывает и без болезни печени: после долгого голодания, тяжёлой нагрузки, от некоторых лекарств, при синдроме Жильбера — безобидной наследственной особенности. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем отдельно сдавать прямой и непрямой билирубин?", "a": "Общий билирубин — их сумма. Непрямой печень ещё не переработала, прямой — уже переработала. По тому, какой из них повышен, врач понимает, где искать причину."}, {"q": "Можно ли голодать перед анализом дольше 12 часов?", "a": "Не нужно: долгое голодание само по себе может повысить билирубин. Достаточно не есть 12 часов, воду пить можно."}], "together": ["40-036", "40-026", "20-017"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-036": {"lede": "Покажет, сколько в крови билирубина, который печень уже переработала, и нет ли помех оттоку желчи.", "blocks": [{"h": "Что это", "p": ["Билирубин — жёлтое вещество, которое образуется при обновлении эритроцитов. Печень перерабатывает его в прямой (связанный) билирубин и выводит с желчью в кишечник, поэтому в крови прямого билирубина обычно совсем мало.", "Если его становится больше, дело чаще всего в печени или в оттоке желчи."]}, {"h": "Какие бывают признаки", "p": ["Когда прямого билирубина в крови много, бывает:"], "list": ["желтизна кожи и белков глаз", "тёмная моча", "светлый кал", "кожный зуд", "боль или тяжесть справа под рёбрами"], "note": "Если пожелтели кожа или белки глаз, не откладывайте визит к врачу."}, {"h": "Когда назначают", "list": ["если общий билирубин повышен — чтобы понять причину", "при желтизне кожи и глаз, тёмной моче, светлом кале", "при боли справа под рёбрами, камнях в желчном пузыре", "у младенца, если желтуха держится дольше обычного", "при приёме лекарств, которые могут влиять на печень"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа. Чистую воду без газа пить можно.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За 30 минут до анализа — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий прямой билирубин обычно не беспокоит врачей. Повышенный может говорить о болезнях печени или о том, что желчь плохо оттекает, например из-за камней в желчном пузыре; иногда его повышают некоторые лекарства. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем прямой билирубин отличается от непрямого?", "a": "Непрямой печень ещё не переработала, прямой — уже переработала. Повышение прямого чаще связано с печенью и оттоком желчи, непрямого — с разрушением эритроцитов или синдромом Жильбера."}, {"q": "У младенца долго не проходит желтуха — что сдают?", "a": "Обычно педиатр назначает общий и прямой билирубин. Обратитесь к нему, если желтуха держится дольше обычного, моча тёмная или кал светлый."}], "together": ["40-035", "40-121", "21.120"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-037": {"lede": "Покажет, сколько в крови билирубина, который печень ещё не переработала.", "blocks": [{"h": "Что это", "p": ["Билирубин — жёлтое вещество, которое образуется, когда организм обновляет эритроциты и разрушает старые. Сначала он непрямой (свободный): кровь приносит его в печень, и там его перерабатывают.", "Непрямого билирубина становится больше, если эритроциты разрушаются быстрее обычного или печень перерабатывает его медленнее."]}, {"h": "Какие бывают признаки", "p": ["Если непрямого билирубина много, бывает:"], "list": ["желтизна кожи и белков глаз", "лёгкая желтизна глаз после голодания, недосыпа или болезни", "слабость, бледность, одышка — если эритроциты разрушаются слишком быстро", "желтизна кожи у новорождённого в первые дни жизни"], "note": "Небольшое повышение может ничем не ощущаться."}, {"h": "Когда назначают", "list": ["если повышен общий билирубин — чтобы понять причину", "при анемии — чтобы проверить, не разрушаются ли эритроциты слишком быстро", "если глаза иногда слегка желтеют, например после голодания", "у младенцев с желтухой — по назначению педиатра"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа. Чистую воду без газа пить можно.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За 30 минут до анализа — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий непрямой билирубин обычно не беспокоит врачей, а повышенный бывает, когда эритроциты разрушаются быстрее обычного, и при синдроме Жильбера — безобидной наследственной особенности. Без болезни он может подняться после долгого голодания, тяжёлой нагрузки, от некоторых лекарств, а при синдроме Жильбера — и при нехватке воды. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Как определяют непрямой билирубин?", "a": "Обычно его рассчитывают: из общего билирубина вычитают прямой. Поэтому в лаборатории измеряют оба этих показателя."}, {"q": "Что такое синдром Жильбера?", "a": "Частая наследственная особенность: печень медленнее перерабатывает билирубин, и глаза иногда слегка желтеют. Печень при этом не повреждается, лечения обычно не нужно. Подтверждает его врач."}], "together": ["40-035", "40-036", "20-017"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-001": {"lede": "Покажет, сколько всего белков в крови — так врач оценивает питание, работу печени и почек.", "blocks": [{"h": "Что это", "p": ["Белки — строительный материал для клеток и тканей. В крови они ещё и «транспорт»: переносят гормоны и другие вещества, удерживают жидкость в сосудах, а антитела защищают от инфекций.", "Общий белок — это все белки крови вместе: альбумин, который вырабатывает печень, и глобулины, к которым относятся антитела."]}, {"h": "Какие бывают признаки", "p": ["Если белка в крови мало, бывает:"], "list": ["отёки на ногах, руках, вокруг глаз", "слабость, быстрая утомляемость", "похудение, если белка не хватает в питании", "пенистая моча — если белок уходит через почки"], "note": "Небольшие изменения белка обычно никак не ощущаются — их находят по анализу."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии крови", "при отёках, похудении, слабости без понятной причины", "при болезнях печени и почек — чтобы следить за состоянием", "если пища плохо усваивается — при болезнях кишечника", "при недостаточном питании"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа. Чистую воду без газа пить можно.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За 30 минут до анализа — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Пониженный белок бывает при болезнях печени, почек и кишечника и когда белка мало в еде, а повышенный — при долгом воспалении и некоторых болезнях крови. Без болезни белок повышается при обезвоживании, снижается после долгого голодания и может меняться от некоторых лекарств. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем общий белок отличается от альбумина?", "a": "Общий белок — все белки крови вместе, альбумин — главный из них. Если общий белок не в норме, врач может добавить альбумин, чтобы понять, какая часть изменилась."}, {"q": "Влияет ли на результат нехватка воды?", "a": "Да: при обезвоживании жидкости в крови меньше, и белок может оказаться выше. Если накануне были рвота, понос или сильная жара, скажите об этом врачу."}], "together": ["40-027", "40-026", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-027": {"lede": "Покажет уровень альбумина — главного белка крови, который вырабатывает печень.", "blocks": [{"h": "Что это", "p": ["Альбумин — главный белок крови, его вырабатывает печень. Он работает «транспортом»: переносит гормоны, витамины, лекарства и кальций, а ещё удерживает жидкость внутри сосудов, чтобы она не уходила в ткани.", "Поэтому по альбумину врач оценивает работу печени и почек и то, хватает ли организму белка."]}, {"h": "Какие бывают признаки", "p": ["Если альбумина мало, бывает:"], "list": ["отёки на ногах, руках, вокруг глаз", "слабость, быстрая утомляемость", "пенистая моча — если альбумин уходит через почки"], "note": "Небольшое снижение альбумина обычно никак не ощущается."}, {"h": "Когда назначают", "list": ["при плановой проверке — в составе биохимии крови", "при отёках, пенистой моче, слабости без понятной причины", "при болезнях печени и почек — чтобы следить за состоянием", "если пища плохо усваивается или питание недостаточное", "перед операцией и при тяжёлых болезнях"]}, {"h": "Как подготовиться", "list": ["Не ешьте 12 часов до анализа. Чистую воду без газа пить можно.", "Детей до года не кормите 30–40 минут до анализа, детей от года до пяти лет — 2–3 часа.", "За 30 минут до анализа — без физических нагрузок, волнений и курения.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Низкий альбумин может говорить о том, что печень вырабатывает его меньше, почки теряют его с мочой, организму не хватает белка из пищи или идёт сильное воспаление. Без болезни альбумин ниже при беременности и после долгого голодания, выше — при обезвоживании; влияют и некоторые лекарства. Одно отклонение — ещё не диагноз. Врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем альбумин в крови отличается от альбумина в моче?", "a": "Анализ крови показывает, сколько альбумина в организме. Анализ мочи помогает рано заметить, что почки пропускают белок: в крови альбумин при этом бывает в норме."}, {"q": "Почему при беременности альбумин ниже?", "a": "Во время беременности жидкой части крови становится больше, и альбумин в ней немного разбавляется. Обычно это не болезнь, но результат оценивает врач."}], "together": ["40-001", "40.120", "40-063"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "30-035": {"lede": "Покажет, сколько в крови инсулина — гормона, который помогает сахару попасть в клетки.", "blocks": [{"h": "Что это", "p": ["Инсулин — гормон поджелудочной железы. Он помогает сахару (глюкозе) перейти из крови в клетки, где тот даёт энергию.", "Анализ показывает, сколько инсулина в крови. Врач обычно оценивает его вместе с глюкозой."]}, {"h": "Какие бывают признаки", "p": ["Если инсулина слишком много и сахар падает, бывает:"], "list": ["потливость и дрожь в руках", "сильный голод", "сердцебиение", "головокружение", "спутанность мыслей"], "note": "Если клетки плохо отвечают на инсулин, это обычно никак не ощущается."}, {"h": "Когда назначают", "list": ["если сахар бывает слишком низким: слабость, дрожь, потливость", "чтобы понять, сколько инсулина вырабатывает поджелудочная железа", "чтобы оценить, как клетки отвечают на инсулин, — по назначению врача", "вместе с глюкозой — для расчёта индекса HOMA"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после последней еды 12 часов. Пить можно только чистую воду.", "За 3 часа до анализа не курите.", "Многие лекарства и биотин (витамин B7) меняют результат. Заранее спросите врача о перерыве за сутки до анализа.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Высокий инсулин при нормальном сахаре может значить, что клетки хуже отвечают на инсулин и железе приходится вырабатывать его больше. Низкий инсулин при высоком сахаре бывает, когда железа вырабатывает его мало. На результат влияют еда незадолго до анализа, некоторые лекарства и уколы инсулина. Норму лаборатория указывает в бланке результата. Результат оценивает врач вместе с глюкозой и другими анализами."]}], "faq": [{"q": "Колю инсулин — можно ли сдать этот анализ?", "a": "Анализ не всегда отличает свой инсулин от введённого, поэтому результат трудно оценить. В таком случае врач чаще назначает С-пептид."}, {"q": "Почему анализ сдают натощак?", "a": "После еды инсулин поднимается, чтобы снизить сахар. Натощак результат проще сравнить с нормой и с прошлыми анализами."}], "together": ["40-047", "30-043", "40-390"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}, "30-043": {"lede": "Покажет, сколько своего инсулина вырабатывает поджелудочная железа.", "blocks": [{"h": "Что это", "p": ["Инсулин — гормон поджелудочной железы, который помогает сахару попасть из крови в клетки. Когда железа его вырабатывает, от исходной молекулы отделяется С-пептид, и оба выходят в кровь в равном количестве.", "В лекарственном инсулине С-пептида нет, поэтому анализ показывает, сколько своего инсулина вырабатывает организм, даже при уколах инсулина."]}, {"h": "Какие бывают признаки", "p": ["Сам С-пептид не ощущается. Анализ назначают при признаках высокого или низкого сахара:"], "list": ["жажда и частое мочеиспускание", "похудение без причины, усталость", "приступы потливости, дрожи, сильного голода"]}, {"h": "Когда назначают", "list": ["если диабет только выявили — чтобы врач уточнил его тип", "если вы колете инсулин — чтобы узнать, сколько своего инсулина вырабатывается", "при приступах низкого сахара без понятной причины"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 8–12 часов. Пить можно только чистую воду.", "Если лечите диабет, спросите врача, как быть с утренними лекарствами.", "Особые правила подготовки уточните у администратора.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Высокий С-пептид бывает, когда поджелудочная железа вырабатывает много инсулина, — например, если клетки плохо на него отвечают. Он бывает выше и при болезнях почек: они медленнее его выводят. Низкий — когда своего инсулина вырабатывается мало. На результат влияют еда и сахар в момент анализа, поэтому врач оценивает С-пептид вместе с глюкозой. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Чем С-пептид отличается от анализа на инсулин?", "a": "Уколы инсулина на С-пептид не влияют. Поэтому он показывает только тот инсулин, который вырабатывает сам организм."}, {"q": "Зачем сдавать вместе с глюкозой?", "a": "Уровень С-пептида зависит от сахара в момент анализа. Вместе с глюкозой врачу легче понять, хватает ли своего инсулина."}], "together": ["40-047", "30-035", "40-141"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}, "18.101": {"lede": "Покажет, как организм справляется с сахаром после сладкого раствора глюкозы.", "blocks": [{"h": "Что это", "p": ["Глюкоза — сахар крови, главный источник энергии. После еды гормон инсулин помогает ей перейти в клетки, и сахар снижается.", "Во время теста кровь из вены берут натощак, затем вы выпиваете раствор глюкозы — очень сладкую воду. Через время, которое назначит врач, кровь берут снова: так видно, как организм справляется с сахаром."]}, {"h": "Какие бывают признаки", "p": ["Нарушения обмена сахара долго могут ничем не проявляться. Иногда бывает:"], "list": ["жажда и частое мочеиспускание", "усталость", "раны и царапины долго заживают"], "note": "Поэтому тест назначают и без жалоб."}, {"h": "Когда назначают", "p": ["Тест проводят только по направлению врача, например:"], "list": ["если сахар натощак или гликированный гемоглобин на границе нормы", "при лишнем весе, высоком давлении, диабете у родственников", "если раньше был диабет беременных или рождался крупный ребёнок"]}, {"h": "Как подготовиться", "list": ["Три дня перед тестом ешьте как обычно, без диет, и не меняйте привычную активность.", "Последняя еда — за 12 часов, пить можно только чистую воду. Не курите за 30 минут до теста и до его конца.", "Если заболели или недавно начали новые лекарства, скажите врачу: тест могут перенести.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Врач сравнивает сахар натощак и после раствора. Если сахар снижается медленнее обычного, это может говорить о предиабете или диабете. Повышенная глюкоза бывает и временно — при сильном стрессе, тяжёлой болезни, приёме некоторых лекарств. Диагноз диабета ставит врач, обычно после повторного анализа. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Можно ли перед тестом сесть на диету?", "a": "Нет. Три дня до теста ешьте как обычно: если резко ограничить еду, результат может быть неточным."}, {"q": "Бывает ли плохо от сладкого раствора?", "a": "Иногда бывает тошнота, потливость или лёгкое головокружение. Если стало нехорошо, сразу скажите медсестре."}], "together": ["40-141", "00-014"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "18.103": {"lede": "Покажет, как организм будущей мамы справляется с сахаром после сладкого раствора глюкозы.", "blocks": [{"h": "Что это", "p": ["Во время беременности организму нужно больше инсулина — гормона, который снижает сахар крови. Если инсулина не хватает, сахар повышается: это диабет беременных (гестационный).", "На тесте кровь из вены берут натощак, потом вы выпиваете раствор глюкозы — очень сладкую воду, а через время, которое назначит врач, кровь берут снова."]}, {"h": "Какие бывают признаки", "p": ["Диабет беременных обычно никак не ощущается — узнать о нём можно только по анализу."], "note": "Иногда бывают жажда, частое мочеиспускание, усталость — их легко принять за обычные проявления беременности."}, {"h": "Когда назначают", "p": ["Тест проводят только по направлению врача:"], "list": ["обычно на 24–28 неделе беременности — по плану врача", "если раньше в этой беременности нарушений сахара не нашли", "в отдельных случаях позже — по решению врача"]}, {"h": "Как подготовиться", "list": ["Три дня до теста ешьте как обычно. Последняя еда — за 12 часов, пить можно только чистую воду.", "При тошноте, рвоте, простуде, температуре скажите врачу: тест могут перенести.", "Витамины и препараты железа обычно пьют после теста — уточните у врача.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Если сахар натощак или после раствора выше нормы, это может говорить о диабете беременных. Обычно он проходит после родов, а во время беременности врач наблюдает маму и малыша внимательнее. На результат влияют строгая диета накануне, болезнь, некоторые лекарства. Диагноз ставит врач — при беременности бывает достаточно одного теста. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем тест, если я хорошо себя чувствую?", "a": "Диабет беременных обычно ничем не ощущается. Тест помогает врачу вовремя его заметить и внимательнее наблюдать вас и малыша."}, {"q": "Что делать, пока ждёте повторного взятия крови?", "a": "Спокойно посидите в лаборатории — так результат точнее. Есть и курить до конца теста нельзя."}], "together": ["10-008", "20-001"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "18.110": {"lede": "Покажет средний уровень сахара в крови за последние 2–3 недели.", "blocks": [{"h": "Что это", "p": ["Белки крови, прежде всего альбумин, постепенно соединяются с сахаром: чем выше сахар, тем больше таких соединений. Их общее название — фруктозамин.", "Альбумин обновляется примерно за 2–3 недели, поэтому анализ показывает средний сахар за этот срок. Это быстрее, чем гликированный гемоглобин, который отражает 2–3 месяца."]}, {"h": "Какие бывают признаки", "p": ["Когда сахар долго повышен, бывает:"], "list": ["жажда и частое мочеиспускание", "усталость", "похудение без причины", "раны долго заживают"], "note": "Часто их нет совсем."}, {"h": "Когда назначают", "list": ["если диабет уже есть — чтобы оценить лечение за последние недели", "если лечение недавно изменили и врачу нужен ответ раньше, чем через 3 месяца", "если гликированный гемоглобин может быть неточным, например при некоторых анемиях"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 12 часов, пить можно только чистую воду.", "За 30 минут до анализа не курите, избегайте нагрузок и волнений.", "Скажите врачу, если принимаете большие дозы витамина C: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Чем выше результат, тем выше был сахар в последние 2–3 недели. Анализ бывает неточным, если в крови мало белка — например, при болезнях почек и печени. Диабет по фруктозамину не выявляют: он помогает следить за сахаром, когда диабет уже есть. Результаты лучше сравнивать из одной лаборатории. Норму лаборатория указывает в бланке результата. Результат оценивает врач."]}], "faq": [{"q": "Чем фруктозамин отличается от гликированного гемоглобина?", "a": "Фруктозамин показывает средний сахар за 2–3 недели, гликированный гемоглобин — за 2–3 месяца."}, {"q": "Можно ли по этому анализу узнать, есть ли диабет?", "a": "Нет. Его используют, чтобы следить за сахаром, когда диабет уже есть. Для выявления диабета врач назначает другие анализы."}], "together": ["40-141", "40-047", "40-027"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-390": {"lede": "Покажет по глюкозе и инсулину натощак, насколько хорошо клетки отвечают на инсулин.", "blocks": [{"h": "Что это", "p": ["Инсулин — гормон, который помогает сахару перейти из крови в клетки. Если клетки отвечают на него слабо, поджелудочной железе приходится вырабатывать больше инсулина — это называют инсулинорезистентностью.", "Индекс HOMA рассчитывают по двум анализам натощак — глюкозе и инсулину. Так врач оценивает, насколько хорошо организм отвечает на свой инсулин."]}, {"h": "Какие бывают признаки", "p": ["Сниженная чувствительность к инсулину обычно никак не ощущается — узнать о ней можно только по анализам."], "note": "Чаще её находят при лишнем весе, особенно на животе, малоподвижной жизни, диабете у родственников. Но бывает и без этого."}, {"h": "Когда назначают", "list": ["при лишнем весе, особенно на животе, — по назначению врача", "если сахар натощак на границе нормы", "при синдроме поликистозных яичников — по назначению гинеколога"]}, {"h": "Как подготовиться", "list": ["Утром строго натощак: после еды 12 часов, пить можно только чистую воду. Кровь на глюкозу и инсулин берут в одно посещение.", "За 3 часа до анализа не курите.", "Особые правила подготовки уточните у администратора.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Чем выше индекс, тем хуже клетки отвечают на инсулин. Результат меняется от еды накануне, стресса, болезни, некоторых лекарств, поэтому врач может попросить пересдать. При уколах инсулина индекс обычно не используют. Высокий индекс — не диагноз диабета: врач оценивает его вместе с глюкозой, гликированным гемоглобином и осмотром. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Можно ли рассчитать индекс по старым анализам?", "a": "Нет. Глюкозу и инсулин нужно сдать в одно утро натощак — только так расчёт имеет смысл."}, {"q": "Высокий индекс — это диабет?", "a": "Нет. Он говорит о том, что клетки хуже отвечают на инсулин. Что делать дальше, врач решит по другим анализам и осмотру."}], "together": ["40-141", "00-014"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "40-004": {"lede": "Покажет уровень мочевой кислоты — вещества, избыток которого может откладываться в суставах и почках.", "blocks": [{"h": "Что это", "p": ["Мочевая кислота образуется, когда организм расщепляет пурины — вещества из собственных клеток и некоторых продуктов, например мяса.", "Почки выводят её с мочой. Если её образуется много или почки выводят мало, она может откладываться кристаллами в суставах и почках."]}, {"h": "Какие бывают признаки", "p": ["Повышенная мочевая кислота часто никак не ощущается. Если она откладывается, бывает:"], "list": ["внезапная сильная боль в суставе, чаще в большом пальце стопы", "сустав опухает, краснеет, становится горячим", "резкая боль в пояснице или боку", "кровь в моче"]}, {"h": "Когда назначают", "list": ["в плановой биохимии крови", "при внезапной боли и отёке сустава", "при камнях в почках или чтобы оценить работу почек", "при лечении, которое снижает мочевую кислоту, — для контроля"]}, {"h": "Как подготовиться", "list": ["Утром натощак: после еды 12 часов, пить можно чистую воду без газа.", "Детям до года — не кормить за 30–40 минут до анализа, детям 1–5 лет — за 2–3 часа.", "За 30 минут не курите, избегайте нагрузок и волнений.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышение бывает, когда мочевой кислоты образуется много или почки выводят её медленнее. Без болезни её поднимают мясо, морепродукты, алкоголь, сладкие напитки, мочегонные лекарства. Высокий результат не всегда значит подагру. Низкий бывает редко и обычно не вызывает проблем. Одно отклонение — ещё не диагноз: врач оценивает показатель вместе с другими анализами и может попросить пересдать. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Высокая мочевая кислота — это подагра?", "a": "Не обязательно. Она бывает повышена и без боли в суставах. Подагру определяет врач по жалобам, осмотру и другим обследованиям."}, {"q": "Можно ли накануне есть мясо?", "a": "Лучше накануне не переедать мяса и не пить алкоголь: они могут временно повысить результат."}], "together": ["40-063", "40-077", "10-008"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "30-009": {"lede": "Покажет, сколько в крови работающего тироксина — главного гормона щитовидной железы.", "blocks": [{"h": "Что это", "p": ["Тироксин (Т4) — главный гормон щитовидной железы: от него зависят обмен веществ, силы, тепло тела и сердцебиение.", "Почти весь Т4 в крови «едет» на белках-переносчиках и не действует, а работает небольшая свободная часть, которая попадает в клетки. Анализ показывает именно эту свободную часть."]}, {"h": "Какие бывают признаки", "p": ["Если гормонов щитовидной железы мало или много, бывает:"], "list": ["мало гормонов: усталость, сонливость, зябкость", "мало гормонов: прибавка веса, сухая кожа, запоры", "много гормонов: сердцебиение, потливость, дрожь в руках", "много гормонов: похудение без причины, раздражительность"]}, {"h": "Когда назначают", "list": ["если ТТГ выше или ниже нормы — чтобы понять, как работает щитовидная железа", "при усталости, сердцебиении, изменении веса без понятной причины", "при лечении гормонами щитовидной железы — вместе с ТТГ", "при беременности, если есть болезни щитовидной железы", "при болезнях гипофиза, когда по ТТГ трудно судить о работе железы"]}, {"h": "Как подготовиться", "list": ["За 2–3 часа до анализа не ешьте, чистую воду без газа пить можно. Ребёнка до года не кормите за 30–40 минут.", "За сутки избегайте тяжёлых нагрузок и волнений, за 3 часа не курите.", "Принимаете гормоны щитовидной железы или стероидные гормоны — спросите врача, пить ли таблетку до анализа. Скажите и о биотине (витамине B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Если свободный Т4 ниже нормы, гормонов щитовидной железы может не хватать, если выше — их может быть слишком много. Врач смотрит его вместе с ТТГ: этот гормон гипофиза, небольшой железы в мозге, «подгоняет» щитовидную железу. На результат влияют и тяжёлые болезни, некоторые лекарства, таблетка гормонов перед анализом. Норму лаборатория указывает в бланке результата. Оценивает результат врач."]}], "faq": [{"q": "Чем свободный Т4 отличается от общего?", "a": "Общий Т4 — весь гормон в крови: и тот, что на белках, и свободный. Свободный — только работающая часть. Его назначают чаще: он меньше зависит от количества белков в крови."}, {"q": "Почему сначала проверяют ТТГ, а не Т4?", "a": "ТТГ обычно проверяют первым. Если он отклоняется от нормы, врач добавляет другие анализы, например свободный Т4."}], "together": ["30-010", "28.135"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}, "30-007": {"lede": "Покажет, сколько в крови свободного Т3 — самого активного гормона щитовидной железы.", "blocks": [{"h": "Что это", "p": ["Трийодтиронин (Т3) — самый активный гормон щитовидной железы. Часть его делает сама железа, а больше всего его получается из тироксина (Т4) в печени и других органах.", "Почти весь Т3 в крови «едет» на белках-переносчиках, а работает небольшая свободная часть — её и показывает анализ."]}, {"h": "Какие бывают признаки", "p": ["Если гормонов щитовидной железы слишком много, бывает:"], "list": ["частое сердцебиение, даже в покое", "потливость, плохая переносимость жары", "дрожь в руках, раздражительность, плохой сон", "похудение без понятной причины"]}, {"h": "Когда назначают", "list": ["если ТТГ ниже нормы — вместе со свободным Т4", "при сердцебиении, потливости, похудении без понятной причины", "во время лечения, если щитовидная железа работала слишком активно", "при приёме гормонов щитовидной железы — по решению врача"]}, {"h": "Как подготовиться", "list": ["За 2–3 часа до анализа не ешьте, чистую воду без газа пить можно. Ребёнка до года не кормите за 30–40 минут.", "За сутки избегайте тяжёлых нагрузок и волнений, за 3 часа не курите.", "Принимаете гормоны щитовидной железы или стероидные гормоны — спросите врача, пить ли таблетку до анализа. Скажите и о биотине (витамине B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный свободный Т3 бывает, когда щитовидная железа работает слишком активно. Иногда повышен только Т3, а Т4 в норме, поэтому врач может назначить оба анализа. Пониженный Т3 бывает при нехватке гормонов, а также при тяжёлых болезнях, не связанных с щитовидной железой. Норму лаборатория указывает в бланке результата. Оценивает результат врач — вместе с ТТГ и Т4."]}], "faq": [{"q": "Чем свободный Т3 отличается от общего?", "a": "Общий Т3 — весь гормон в крови, вместе с тем, что «едет» на белках. Свободный — только работающая часть. Общий меняется вместе с количеством белков, например при беременности."}, {"q": "Почему Т3 редко проверяют, когда гормонов мало?", "a": "Когда гормонов мало, Т3 часто долго остаётся в норме и снижается позже других показателей. Поэтому в таких случаях врач смотрит ТТГ и свободный Т4."}], "together": ["30-010", "30-009", "28.145"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}, "30-008": {"lede": "Покажет, сколько в крови тироксина — главного гормона щитовидной железы — всего, а не только свободного.", "blocks": [{"h": "Что это", "p": ["Тироксин (Т4) — главный гормон щитовидной железы: от него зависят обмен веществ, силы, тепло тела и сердцебиение.", "Почти весь Т4 в крови «едет» на белках-переносчиках, как пассажиры в автобусе, и не действует, а работает лишь небольшая свободная часть. Общий Т4 — это весь гормон сразу: и на белках, и свободный."]}, {"h": "Какие бывают признаки", "p": ["Если гормонов щитовидной железы мало или много, бывает:"], "list": ["мало гормонов: усталость, сонливость, зябкость", "мало гормонов: прибавка веса, сухая кожа, запоры", "много гормонов: сердцебиение, потливость, дрожь в руках", "много гормонов: похудение без причины, раздражительность"]}, {"h": "Когда назначают", "list": ["если ТТГ выше или ниже нормы", "при усталости, сердцебиении, изменении веса без понятной причины", "при лечении болезней щитовидной железы — чтобы проверить, как оно действует", "если у близких родственников есть болезни щитовидной железы"]}, {"h": "Как подготовиться", "list": ["За 2–3 часа до анализа не ешьте, чистую воду без газа пить можно. Ребёнка до года не кормите за 30–40 минут.", "За сутки избегайте тяжёлых нагрузок и волнений, за 3 часа не курите.", "Принимаете гормоны щитовидной железы или стероидные гормоны — спросите врача, пить ли таблетку до анализа. Скажите и о биотине (витамине B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный общий Т4 может говорить об избытке гормонов, пониженный — об их нехватке. Но он зависит и от белков-переносчиков: при беременности и приёме таблеток с эстрогенами их больше, и общий Т4 выше, хотя железа работает как обычно. Снижать его могут тяжёлые болезни и некоторые лекарства. Норму лаборатория указывает в бланке результата. Врач оценивает результат вместе с ТТГ и свободным Т4."]}], "faq": [{"q": "Что лучше сдать — общий или свободный Т4?", "a": "Решает врач. Свободный Т4 назначают чаще: он меньше зависит от белков-переносчиков. Общий врач может добавить к нему или назначить отдельно."}, {"q": "При беременности общий Т4 выше — это плохо?", "a": "Не обязательно. Во время беременности белков-переносчиков в крови больше, поэтому общий Т4 обычно выше, чем до неё. Что значит результат, скажет врач."}], "together": ["30-010", "30-009"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}, "30-006": {"lede": "Покажет, сколько в крови Т3 — самого активного гормона щитовидной железы — всего, а не только свободного.", "blocks": [{"h": "Что это", "p": ["Трийодтиронин (Т3) — самый активный гормон щитовидной железы, больше всего его получается из тироксина (Т4) в печени и других органах.", "Почти весь Т3 в крови «едет» на белках-переносчиках, а работает небольшая свободная часть. Общий Т3 — это весь гормон сразу: и на белках, и свободный."]}, {"h": "Какие бывают признаки", "p": ["Если гормонов щитовидной железы слишком много, бывает:"], "list": ["частое сердцебиение, даже в покое", "потливость, плохая переносимость жары", "дрожь в руках, раздражительность, плохой сон", "похудение без понятной причины"]}, {"h": "Когда назначают", "list": ["если ТТГ ниже нормы — чтобы понять, насколько активно работает железа", "при сердцебиении, потливости, похудении без понятной причины", "во время лечения, если щитовидная железа работала слишком активно"]}, {"h": "Как подготовиться", "list": ["За 2–3 часа до анализа не ешьте, чистую воду без газа пить можно. Ребёнка до года не кормите за 30–40 минут.", "За сутки избегайте тяжёлых нагрузок и волнений, за 3 часа не курите.", "Принимаете гормоны щитовидной железы или стероидные гормоны — спросите врача, пить ли таблетку до анализа. Скажите и о биотине (витамине B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенный общий Т3 может говорить о том, что щитовидная железа работает слишком активно. Но он зависит и от белков-переносчиков: при беременности и приёме таблеток с эстрогенами их больше, и общий Т3 бывает выше без болезни железы. Снижается он при нехватке гормонов и при тяжёлых болезнях, не связанных с железой. Норму лаборатория указывает в бланке результата. Врач оценивает результат вместе с ТТГ и Т4."]}], "faq": [{"q": "Чем общий Т3 отличается от свободного?", "a": "Общий — весь Т3 в крови, свободный — только работающая часть. На общий влияет количество белков-переносчиков, например при беременности. Какой анализ нужен, решает врач."}, {"q": "Почему врач смотрит и Т3, и Т4?", "a": "Иногда, когда железа работает слишком активно, повышен только Т3, а Т4 в норме. Поэтому врач может назначить оба анализа вместе с ТТГ."}], "together": ["30-010", "30-008"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}, "28.135": {"lede": "Покажет, есть ли в крови антитела к ТПО — веществу, которое помогает щитовидной железе делать гормоны.", "blocks": [{"h": "Что это", "p": ["Тиреопероксидаза (ТПО) — вещество внутри щитовидной железы, которое помогает ей вырабатывать гормоны.", "Антитела — защитные белки иммунитета. Иногда иммунитет по ошибке направляет их против своей щитовидной железы, и со временем её работа может меняться. Анализ показывает, есть ли в крови антитела к ТПО."]}, {"h": "Какие бывают признаки", "p": ["Сами антитела никак не ощущаются. Признаки бывают, только если меняется работа железы:"], "list": ["мало гормонов: усталость, зябкость, прибавка веса, сухая кожа", "много гормонов: сердцебиение, потливость, похудение без причины", "увеличение щитовидной железы — припухлость спереди на шее"]}, {"h": "Когда назначают", "list": ["если ТТГ выше или ниже нормы — чтобы понять причину", "при планировании беременности и при первом визите по беременности — вместе с ТТГ", "если у близких родственников есть болезни щитовидной железы", "при диабете первого типа и других болезнях, когда иммунитет атакует свои ткани"]}, {"h": "Как подготовиться", "list": ["Особой подготовки обычно не нужно. Если в тот же день сдаёте биохимию, приходите натощак. Точные правила уточните у администратора.", "Принимаете гормоны щитовидной железы — спросите врача, пить ли таблетку до анализа.", "Скажите врачу, если принимаете биотин (витамин B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенные антитела к ТПО значат, что иммунитет реагирует на щитовидную железу. Это ещё не диагноз: такие антитела бывают и у здоровых людей, и у большинства из них железа работает нормально. Если гормоны в норме, повышенные антитела — повод наблюдать ТТГ, а не обязательно лечиться. Если антител нет, это не исключает все болезни щитовидной железы. Норму лаборатория указывает в бланке результата. Оценивает результат врач."]}], "faq": [{"q": "Антитела повышены — значит, нужно лечиться?", "a": "Не обязательно. Если щитовидная железа работает нормально, по клиническим рекомендациям достаточно время от времени проверять ТТГ. Что делать дальше, решает врач."}, {"q": "Нужно ли пересдавать антитела к ТПО?", "a": "Обычно нет. Клинические рекомендации не советуют проверять их снова, чтобы следить за болезнью: за работой железы врач следит по ТТГ."}], "together": ["30-010", "30-009", "50-126"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "50-126": {"lede": "Покажет, есть ли в крови антитела к тиреоглобулину — белку, из которого щитовидная железа делает гормоны.", "blocks": [{"h": "Что это", "p": ["Тиреоглобулин (ТГ) — белок щитовидной железы, из которого она делает свои гормоны.", "Иногда иммунитет по ошибке вырабатывает против него антитела — защитные белки, которые обычно борются с микробами. Анализ показывает, есть ли такие антитела в крови."]}, {"h": "Какие бывают признаки", "p": ["Сами антитела ничем не ощущаются. Если со временем меняется работа железы, бывает:"], "list": ["когда гормонов мало: усталость, сонливость, зябкость, прибавка веса", "когда гормонов много: сердцебиение, потливость, дрожь в руках", "припухлость спереди на шее, если железа увеличилась"]}, {"h": "Когда назначают", "list": ["если ТТГ выше или ниже нормы — вместе с антителами к ТПО", "при увеличении щитовидной железы", "при наблюдении после лечения рака щитовидной железы — вместе с тиреоглобулином"]}, {"h": "Как подготовиться", "list": ["Особой подготовки обычно не нужно. Если в тот же день сдаёте биохимию, приходите натощак. Точные правила уточните у администратора.", "Принимаете гормоны щитовидной железы — спросите врача, пить ли таблетку до анализа.", "Скажите врачу, если принимаете биотин (витамин B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенные антитела к ТГ значат, что иммунитет реагирует на щитовидную железу. Сами по себе они не диагноз: такие антитела бывают и у здоровых людей. Врач оценивает их вместе с ТТГ, Т4 и антителами к ТПО. Если железа работает нормально, повышенные антитела — повод наблюдать ТТГ, а не обязательно лечиться. Норму лаборатория указывает в бланке результата. Оценивает результат врач."]}], "faq": [{"q": "Чем антитела к ТГ отличаются от антител к ТПО?", "a": "Это антитела к двум разным веществам щитовидной железы. У одних людей находят одни антитела, у других — другие, у третьих — оба. Поэтому врач может назначить оба анализа."}, {"q": "Почему их сдают вместе с тиреоглобулином?", "a": "Если в крови есть антитела к ТГ, они мешают точно измерить сам тиреоглобулин. Поэтому при наблюдении после лечения рака щитовидной железы врач оценивает оба анализа вместе."}], "together": ["28.135", "30-010"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "28.145": {"lede": "Покажет, есть ли в крови антитела, которые могут подстёгивать щитовидную железу работать слишком активно.", "blocks": [{"h": "Что это", "p": ["На клетках щитовидной железы есть рецепторы — «замки», к которым подходит ТТГ, гормон гипофиза (небольшой железы в мозге). Так гипофиз «подгоняет» щитовидную железу.", "Иногда иммунитет по ошибке делает антитела, которые садятся на эти «замки»: чаще они подстёгивают железу, реже тормозят её. Анализ показывает, есть ли такие антитела в крови."]}, {"h": "Какие бывают признаки", "p": ["Если антитела подстёгивают железу и гормонов становится много, бывает:"], "list": ["частое сердцебиение", "потливость, дрожь в руках, раздражительность", "похудение без понятной причины", "резь и сухость в глазах, глаза кажутся выпученными"]}, {"h": "Когда назначают", "list": ["если ТТГ снижен, а гормонов щитовидной железы много — чтобы понять причину", "при беременности, если сейчас или раньше была болезнь Грейвса", "перед окончанием лечения — чтобы врач решил, можно ли его завершить"]}, {"h": "Как подготовиться", "list": ["Особой подготовки обычно не нужно. Если в тот же день сдаёте биохимию, приходите натощак. Точные правила уточните у администратора.", "Принимаете гормоны щитовидной железы — спросите врача, пить ли таблетку до анализа.", "Скажите врачу, если принимаете биотин (витамин B7) из добавок для волос и ногтей: он может исказить результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Повышенные антитела к рецептору ТТГ чаще всего бывают при болезни Грейвса (диффузном токсическом зобе): иммунитет заставляет щитовидную железу работать слишком активно. Избыток гормонов бывает и по другим причинам, и если антител нет, врач ищет их. Он оценивает результат вместе с ТТГ, Т4, Т3 и УЗИ. Норму лаборатория указывает в бланке результата."]}], "faq": [{"q": "Зачем этот анализ при беременности?", "a": "Такие антитела могут проходить через плаценту и влиять на щитовидную железу ребёнка. Поэтому женщинам, у которых сейчас или раньше была болезнь Грейвса, врач может назначить анализ."}, {"q": "Если антитела нашли, это навсегда?", "a": "Не обязательно. Во время лечения уровень антител может снижаться, поэтому врач проверяет его снова перед окончанием курса."}], "together": ["30-010", "30-009", "30-007"], "disclaimer": "Результат анализа — не диагноз. Обсудите его с врачом."}, "32.100": {"lede": "Покажет, как работают околощитовидные железы, которые поддерживают уровень кальция в крови.", "blocks": [{"h": "Что это", "p": ["Паратгормон вырабатывают околощитовидные железы — несколько маленьких желёз позади щитовидной железы. Это отдельный от неё орган со своей работой.", "Паратгормон держит кальций в крови на нужном уровне: когда кальция мало, он берёт его из костей, помогает усвоить из пищи и не даёт терять с мочой. Анализ показывает, как работают эти железы."]}, {"h": "Какие бывают признаки", "p": ["Изменения часто долго ничем не ощущаются. Если кальция в крови слишком много или мало, бывает:"], "list": ["много кальция: жажда, частое мочеиспускание, слабость", "много кальция: боли в костях, камни в почках, переломы при небольшой травме", "мало кальция: покалывание в губах и пальцах, судороги в мышцах"]}, {"h": "Когда назначают", "list": ["если кальций в крови выше или ниже нормы", "при камнях в почках, остеопорозе, переломах при небольшой травме", "при хронической болезни почек и на диализе", "после операции на щитовидной или околощитовидных железах"]}, {"h": "Как подготовиться", "list": ["Лучше сдавать утром натощак: после еды 8–12 часов, чистую воду пить можно. Точные правила уточните у администратора.", "Скажите врачу, если принимаете витамин D, кальций или биотин (витамин B7) из добавок для волос и ногтей: они могут влиять на результат.", "Лекарства сами не отменяйте — скажите о них врачу."]}, {"h": "Как понять результат", "p": ["Высокий паратгормон вместе с высоким кальцием может говорить о том, что одна из околощитовидных желёз работает слишком активно. Если паратгормон высокий, а кальций снижен, часто это ответ организма на нехватку витамина D или болезни почек. Низкий паратгормон бывает после операций на шее и при избытке витамина D или кальция из добавок. Норму лаборатория указывает в бланке результата. Оценивает результат врач."]}], "faq": [{"q": "При чём тут щитовидная железа?", "a": "Околощитовидные железы лежат рядом с ней, но это отдельный орган. Они управляют кальцием, а не обменом веществ, поэтому анализы щитовидной железы их работу не показывают."}, {"q": "Зачем вместе с паратгормоном сдавать кальций?", "a": "Паратгормон и кальций влияют друг на друга. Один и тот же уровень гормона значит разное при высоком и низком кальции, поэтому врач смотрит их вместе."}], "together": ["40-297", "40-063", "40-121"], "disclaimer": "Уровень гормонов зависит от многих причин — результат оценивает врач."}};
